    in = 8'b11111111; #10;
    if (out !== 8'b11111111) $display("*** TEST RESULT: FAIL ***");

    in = 8'b10101010; #10;
    if (out !== 8'b01010101) $display("*** TEST RESULT: FAIL ***");

    in = 8'b11001100; #10;
    if (out !== 8'b00110011) $display("*** TEST RESULT: FAIL ***");

    // If all tests pass
    $display("*** TEST RESULT: PASS ***");
    $finish;
  end
endmodule

