test_code:
`timescale 1ns/1ps

module tb;
    reg  [7:0] in;
    wire [7:0] out;

    // Instantiate DUT strictly as required
    TopModule dut (
        .in(in),
        .out(out)
    );

    integer errors = 0;
    integer i;
    reg [7:0] expected;

    initial begin
        // Test various bit patterns including all zeros, all ones, walking ones, and alternating bits
        // Corner cases: 0x00, 0xFF, 0x55, 0xAA, 0x01, 0x80

        // 1. Direct targeted corner cases
        in = 8'h00; #10;
        expected = 8'h00;
        if (out !== expected) errors = errors + 1;

        in = 8'hFF; #10;
        expected = 8'hFF;
        if (out !== expected) errors = errors + 1;

        in = 8'h01; #10; // {0,0,0,0,0,0,0,1} reversed -> {1,0,0,0,0,0,0,0} = 8'h80
        expected = 8'h80;
        if (out !== expected) errors = errors + 1;

        in = 8'h80; #10; // {1,0,0,0,0,0,0,0} reversed -> {0,0,0,0,0,0,0,1} = 8'h01
        expected = 8'h01;
        if (out !== expected) errors = errors + 1;

        in = 8'h55; #10; // 01010101 reversed -> 10101010 = 8'hAA
        expected = 8'hAA;
        if (out !== expected) errors = errors + 1;

        in = 8'hAA; #10; // 10101010 reversed -> 01010101 = 8'h55
        expected = 8'h55;
        if (out !== expected) errors = errors + 1;

        // 2. Systematic bounded loop checking all or a representative subset of combinations
        for (i = 0; i < 256; i = i + 1) begin
            in = i[7:0];
            #10;
            // Compute expected bit reversal behavior explicitly
            expected = {in[0], in[1], in[2], in[3], in[4], in[5], in[6], in[7]};

            // Use strictly `!==` for 4-State output equality as required
            if (out !== expected) begin
                errors = errors + 1;
            end
        end

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

