module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg [7:0] in;
    wire [7:0] out;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .in(in),
        .out(out)
    );

    // 3. Stimulus & self-checking
    integer errors = 0;
    reg [7:0] expected;
    integer i;
    integer bit_idx;

    initial begin
        // Initialize inputs
        in = 8'h00;
        #10;

        // Test exhaustive or key patterns for an 8-bit bit-reversal module
        // We'll test a set of directed vectors and a bounded loop of pseudo-random/sequential values.

        // Test vector 1: All zeros
        in = 8'h00;
        expected = 8'h00;
        #5;
        if (out !== expected) begin
            errors = errors + 1;
            $display("Mismatch: in = %b, got = %b, expected = %b", in, out, expected);
        end

        // Test vector 2: All ones
        in = 8'hFF;
        expected = 8'hFF;
        #5;
        if (out !== expected) begin
            errors = errors + 1;
            $display("Mismatch: in = %b, got = %b, expected = %b", in, out, expected);
        end

        // Test vector 3: Alternating patterns
        in = 8'h55; // 01010101
        expected = 8'hAA; // 10101010
        #5;
        if (out !== expected) begin
            errors = errors + 1;
            $display("Mismatch: in = %b, got = %b, expected = %b", in, out, expected);
        end

        // Test vector 4: Single hot bits moving across
        for (i = 0; i < 8; i = i + 1) begin
            in = (1 << i);
            // Expected is bit-reversed: bit i goes to bit (7-i)
            expected = 8'h00;
            expected[7 - i] = 1'b1;
            #5;
            if (out !== expected) begin
                errors = errors + 1;
                $display("Mismatch: in = %b, got = %b, expected = %b", in, out, expected);
            end
        end

        // Test vector 5: Bounded loop covering asymmetric/complex byte values
        for (i = 1; i < 10; i = i + 1) begin
            in = i[7:0] * 17; // Generates various patterns like 17, 34, 51, etc.

            // Compute expected bit-reversal algorithmically
            expected = 8'h00;
            for (bit_idx = 0; bit_idx < 8; bit_idx = bit_idx + 1) begin
                expected[7 - bit_idx] = in[bit_idx];
            end

            #5;
            if (out !== expected) begin
                errors = errors + 1;
                $display("Mismatch: in = %b, got = %b, expected = %b", in, out, expected);
            end
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

