    // Instantiate TopModule dut
    TopModule dut (
        .in(in),
        .sel(sel),
        .out(out)
    );

    integer errors = 0;
    integer i;
    reg [3:0] expected;

    initial begin
        // Initialize inputs
        in = 1024'h0;
        sel = 8'h0;
        #10;

        // Test 1: Zero-out pattern with various selections
        in = 1024'h0;
        for (i = 0; i < 16; i = i + 1) begin
            sel = i[7:0];
            #5;
            expected = 4'h0;
            if (out !== expected) begin
                errors = errors + 1;
            end
        end

        // Test 2: Walking pattern / specific bit chunks
        // Fill 'in' with recognizable 4-bit nibbles: in[4*i +: 4] = i[3:0]
        for (i = 0; i < 256; i = i + 1) begin
            in[i*4 +: 4] = i[3:0];
        end

        // Check a representative set of selections (bounded loop)
        for (i = 0; i < 256; i = i + (256/16)) begin
            sel = i[7:0];
            #5;
            expected = i[3:0];
            if (out !== expected) begin
                errors = errors + 1;
            end
        end

        // Test 3: Edge cases (sel = 255)
        sel = 8'hFF;
        #5;
        expected = in[1023:1020];
        if (out !== expected) begin
            errors = errors + 1;
        end

        // Test 4: Random verification vectors
        in = 1024'hFEDCBA9876543210FEDCBA9876543210FEDCBA9876543210FEDCBA9876543210;
        sel = 8'd0;   #5; if (out !== 4'h0) errors = errors + 1;
        sel = 8'd1;   #5; if (out !== 4'h1) errors = errors + 1;
        sel = 8'd10;  #5; if (out !== 4'hA) errors = errors + 1;
        sel = 8'd15;  #5; if (out !== 4'hF) errors = errors + 1;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

