        end

        // sel = 1
        sel = 8'h01;
        #5;
        expected = in[sel*4 +: 4];
        if (out !== expected) begin
            errors = errors + 1;
            $display("Mismatch at sel=%0d: got %b, expected %b", sel, out, expected);
        end

        // sel = 10 (arbitrary mid)
        sel = 8'd10;
        #5;
        expected = in[sel*4 +: 4];
        if (out !== expected) begin
            errors = errors + 1;
            $display("Mismatch at sel=%0d: got %b, expected %b", sel, out, expected);
        end

