`timescale 1ns/1ps
module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [3:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk; // 10 ns clock period
    end

    initial begin
        reset = 1; // Start with reset active
        #10; // Wait for a clock cycle
        reset = 0; // Release reset

        // Check the counter values
        repeat (15) begin
            #10; // Wait for the next clock cycle
            if (q !== 4'b0001 && q !== 4'b0010 && q !== 4'b0011 && 
                q !== 4'b0100 && q !== 4'b0101 && q !== 4'b0110 && 
                q !== 4'b0111 && q !== 4'b1000 && q !== 4'b1001 && 
                q !== 4'b1010) begin
                $display("Error: Unexpected value q = %b at time %t", q, $time);
                errors = errors + 1;
            end
        end

        // Final check for wrap-around
        if (q !== 4'b0001) begin
            $display("Error: Counter did not wrap around correctly at time %t", $time);
            errors = errors + 1;
        end

        // Display test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule

