module tb;
    reg a, b, c, d, e;
    wire [24:0] out;

    TopModule dut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .e(e),
        .out(out)
    );

    integer errors = 0;
    integer i;
    reg [4:0] inputs;
    reg [24:0] expected;
    reg in_i, in_j;

    initial begin
        // Test all 32 combinations of {a, b, c, d, e}
        for (i = 0; i < 32; i = i + 1) begin
            inputs = i[4:0];
            a = inputs[4];
            b = inputs[3];
            c = inputs[2];
            d = inputs[1];
            e = inputs[0];

            #5; // Wait for combinatorial propagation

            // Compute expected vector manually
            // Outer loop i from a to e (index 4 down to 0)
            // Inner loop j from a to e (index 4 down to 0)
            // Bit position = i * 5 + j
            // e.g., i=4 (a) -> j=4..0 => out[24..20]
            expected[24] = ~((inputs[4]) ^ (inputs[4]));
            expected[23] = ~((inputs[4]) ^ (inputs[3]));
            expected[22] = ~((inputs[4]) ^ (inputs[2]));
            expected[21] = ~((inputs[4]) ^ (inputs[1]));
            expected[20] = ~((inputs[4]) ^ (inputs[0]));

            expected[19] = ~((inputs[3]) ^ (inputs[4]));
            expected[18] = ~((inputs[3]) ^ (inputs[3]));
            expected[17] = ~((inputs[3]) ^ (inputs[2]));
            expected[16] = ~((inputs[3]) ^ (inputs[1]));
            expected[15] = ~((inputs[3]) ^ (inputs[0]));

            expected[14] = ~((inputs[2]) ^ (inputs[4]));
            expected[13] = ~((inputs[2]) ^ (inputs[3]));
            expected[12] = ~((inputs[2]) ^ (inputs[2]));
            expected[11] = ~((inputs[2]) ^ (inputs[1]));
            expected[10] = ~((inputs[2]) ^ (inputs[0]));

            expected[9]  = ~((inputs[1]) ^ (inputs[4]));
            expected[8]  = ~((inputs[1]) ^ (inputs[3]));
            expected[7]  = ~((inputs[1]) ^ (inputs[2]));
            expected[6]  = ~((inputs[1]) ^ (inputs[1]));
            expected[5]  = ~((inputs[1]) ^ (inputs[0]));

            expected[4]  = ~((inputs[0]) ^ (inputs[4]));
            expected[3]  = ~((inputs[0]) ^ (inputs[3]));
            expected[2]  = ~((inputs[0]) ^ (inputs[2]));
            expected[1]  = ~((inputs[0]) ^ (inputs[1]));
            expected[0]  = ~((inputs[0]) ^ (inputs[0]));

            if (out !== expected) begin
                errors = errors + 1;
                $display("Mismatch at inputs a=%b b=%b c=%b d=%b e=%b: got %b, expected %b",
                         a, b, c, d, e, out, expected);
            end
        end

        // Check X/Z propagation corner cases
        a = 1'bx; b = 1'b0; c = 1'b1; d = 1'bZ; e = 1'b0;
        #5;
        // With X/Z inputs, comparison with !== ensures case inequality handles them properly.
        // We just verify that simulation completes and checks evaluate using case inequality.

        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule

