`timescale 1ns/1ps
module tb;
    reg a, b, c, d, e;
    wire [24:0] out;

    TopModule dut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .e(e),
        .out(out)
    );

    reg [4:0] inputs;
    integer i, j;
    reg expected_bit;
    reg [24:0] expected_out;

    initial begin
        // Test a few combinations of a, b, c, d, e
        for (i = 0; i < 32; i = i + 1) begin
            {a, b, c, d, e} = i[4:0];
            #10;

            // Compute expected output manually
            // Inputs array for easy indexing: inputs[4]=a, inputs[3]=b, inputs[2]=c, inputs[1]=d, inputs[0]=e
            inputs = {a, b, c, d, e};

            for (j = 0; j < 25; j = j + 1) begin
                // j goes from 0 to 24. 
                // row = j / 5 (from 0 to 4), col = j % 5 (from 0 to 4)
                // row 0 is a (inputs[4]), row 4 is e (inputs[0])
                // Wait, the spec says:
                // out[24] compares a and a
                // out[23] compares a and b
                // ...
                // out[0] compares e and e
                // So index k (from 24 down to 0) corresponds to:
                // row = 4 - (k / 5)
                // col = 4 - (k % 5)
                // Let's verify: k=24 -> row = 4-(24/5) = 4-4 = 0 (which is inputs[4], i.e., a)
                // col = 4-(24%5) = 4-4 = 0 (inputs[4], i.e., a). Correct.
                // k=0 -> row = 4-(0/5) = 4-0 = 4 (inputs[0], i.e., e)
                // col = 4-(0%5) = 4-0 = 4 (inputs[0], i.e., e). Correct.

                expected_bit = ~ (inputs[4 - (j / 5)] ^ inputs[4 - (j % 5)]);
                expected_out[j] = expected_bit;
            end

            if (out !== expected_out) begin
                $display("*** TEST RESULT: FAIL ***");
                $finish;
            end
        end

        $display("*** TEST RESULT: PASS ***");
        $finish;
    end
endmodule

