            @(posedge clk);
        end
        #1;
        if (q !== expected_q) begin
            $display("Error: Counter incremented while slowena=0. Expected %d, got %d", expected_q, q);
            errors = errors + 1;
        end

        // Test 2: slowena = 1 (Count up to 9 and wrap around to 0)
        slowena = 1;
        for (i = 0; i < 15; i = i + 1) begin
            @(posedge clk);
            if (expected_q == 4'd9) begin
                expected_q = 4'd0;
