`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    wire [3:0] ena;
    wire [15:0] q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    initial begin
        clk = 0;
        reset = 1;
        #12;

        // Check reset state
        if (q !== 16'h0000) begin
            errors = errors + 1;
            $display("FAIL: Reset state q is %h, expected 16'h0000", q);
        end
        if (ena !== 4'b0000) begin
            errors = errors + 1;
            $display("FAIL: Reset state ena is %b, expected 4'b0000", ena);
        end

        // Release reset
        reset = 0;
        #2;

        // Run through a few clock cycles to test normal increments and enables
        // Cycle 1: q becomes 1, ena[0] should be 0 (since previous q[3:0] was 0, wait, 
        // let's trace: at reset q[3:0]=0. On posedge, q[3:0] != 9, so q[3:0] <= 0+1=1, ena[0] <= 0).
        @(posedge clk);
        #1;
        if (q[3:0] !== 4'd1) begin
            errors = errors + 1;
            $display("FAIL: q[3:0] expected 1, got %d", q[3:0]);
        end

        // Fast forward to when ones digit hits 9 (takes 8 more cycles)
        // Currently at q[3:0] = 1. We need 8 more increments to reach 9.
        repeat (8) @(posedge clk);
        #1;

        if (q[3:0] !== 4'd9) begin
            errors = errors + 1;
            $display("FAIL: q[3:0] expected 9, got %d", q[3:0]);
        end

        // Next clock edge should rollover ones to 0 and assert ena[0] = 1
        @(posedge clk);
        #1;
        if (q[3:0] !== 4'd0) begin
            errors = errors + 1;
            $display("FAIL: Rollover failed, q[3:0] expected 0, got %d", q[3:0]);
        end
        if (ena[0] !== 1'b1) begin
            errors = errors + 1;
            $display("FAIL: ena[0] expected 1 on ones rollover, got %b", ena[0]);
        end
        if (q[7:4] !== 4'd1) begin
            errors = errors + 1;
            $display("FAIL: Tens digit expected to increment to 1, got %d", q[7:4]);
        end

        // Check asynchronous/synchronous reset behavior check
        @(posedge clk);
        reset = 1;
        #2;
        if (q !== 16'h0000 || ena !== 4'b0000) begin
            errors = errors + 1;
            $display("FAIL: Synchronous/Asynchronous reset failed. q=%h, ena=%b", q, ena);
        end

        reset = 0;
        #10;

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

