module tb;
    reg clk;
    reg resetn;
    reg [1:0] byteena;
    reg [15:0] d;
    wire [15:0] q;

    // Instantiate the DUT
    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .byteena(byteena),
        .d(d),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg [15:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        resetn = 0;
        byteena = 2'b00;
        d = 16'h0000;
        expected_q = 16'h0000;

        // Test 1: Check synchronous active-low reset
        #12;
        if (q !== 16'h0000) errors = errors + 1;

        // Release reset, test no byte enable (q should hold state 0)
        resetn = 1;
        byteena = 2'b00;
        d = 16'hAAAA;
        #10;
        if (q !== expected_q) errors = errors + 1; // expected_q is still 0000

        // Test 2: Write lower byte only (byteena[0] = 1, byteena[1] = 0)
        byteena = 2'b01;
        d = 16'h1234;
        expected_q[7:0] = 16'h34;
        // Upper byte expected_q[15:8] should remain 00
        #10;
        if (q !== expected_q) errors = errors + 1;

        // Test 3: Write upper byte only (byteena[0] = 0, byteena[1] = 1)
        byteena = 2'b10;
        d = 16'h5678;
        expected_q[15:8] = 16'h56;
        // Lower byte expected_q[7:0] should retain previous value (34)
        #10;
        if (q !== expected_q) errors = errors + 1;

        // Test 4: Write both bytes simultaneously (byteena = 11)
        byteena = 2'b11;
        d = 16'hABCD;
        expected_q = 16'hABCD;
        #10;
        if (q !== expected_q) errors = errors + 1;

        // Test 5: Assert reset asynchronously/synchronously mid-operation
        resetn = 0;
        byteena = 2'b11;
        d = 16'hFFFF;
        expected_q = 16'h0000;
        #10;
        if (q !== expected_q) errors = errors + 1;

        // Test 6: Release reset and verify partial write again
        resetn = 1;
        byteena = 2'b01;
        d = 16'h0055;
        expected_q = 16'h0055; // upper is 0, lower is 55
        #10;
        if (q !== expected_q) errors = errors + 1;

        // Final result reporting
        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

