    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .byteena(byteena),
        .d(d),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    initial begin
        // Initialize signals
        clk = 0;
        resetn = 0;
        byteena = 2'b00;
        d = 16'h0000;

        // Apply reset
        #12;
        // Check reset behavior (synchronous reset, active-low)
        if (q !== 16'h0000) begin
            errors = errors + 1;
        end

        // Deassert reset, test writing lower byte only (byteena = 2'b01)
        @(posedge clk);
        #1;
        resetn = 1;
        byteena = 2'b01;
        d = 16'hA55A;

        @(posedge clk);
        #1;
        // Expected: upper byte remains 00, lower byte becomes 5A -> 005A
        if (q !== 16'h005A) begin
            errors = errors + 1;
        end

        // Test writing upper byte only (byteena = 2'b10)
        byteena = 2'b10;
        d = 16'hBCCD;

        @(posedge clk);
        #1;
        // Expected: upper byte becomes BC, lower byte remains 5A -> BC5A
        if (q !== 16'hBC5A) begin
            errors = errors + 1;
        end

        // Test writing both bytes (byteena = 2'b11)
        byteena = 2'b11;
        d = 16'h1234;

        @(posedge clk);
        #1;
        // Expected: 1234
        if (q !== 16'h1234) begin
            errors = errors + 1;
        end

        // Test writing neither byte (byteena = 2'b00)
        byteena = 2'b00;
        d = 16'hFFFF;

        @(posedge clk);
