module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg load;
    reg [9:0] data;
    wire tc;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .data(data),
        .tc(tc)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;

    // Task to check expected output against actual using case inequality
    task check_tc;
        input expected;
        begin
            @(posedge clk);
            #1; // small delay after clock edge for outputs to settle
            if (tc !== expected) begin
                $display("Time %0t: Mismatch! load=%b data=%h | expected tc=%b, got tc=%b", 
                         $time, load, data, expected, tc);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        load = 0;
        data = 10'd0;

        // Wait for a couple of cycles
        @(posedge clk);
        @(posedge clk);

        // Test 1: Load 0 and verify tc is 1 immediately (or next cycle depending on design, 
        // but spec says "Once the internal counter has reached 0, it should stay 0..."). 
        // Wait, if loaded with 0, does it reach 0 immediately? Let's test loading 0.
        load = 1;
        data = 10'd0;
        @(posedge clk);
        #1;
        // Depending on design implementation, loading 0 should set tc to 1 (or 0 if it counts down).
        // Let's observe behavior: Spec says "The output signal tc indicates whether the internal counter has reached 0."
        // Let's test a standard countdown: Load 3.

        load = 1;
        data = 10'd3;
        @(posedge clk);
        #1;
        // After loading 3, tc should be 0 (since count != 0)
        if (tc !== 1'b0) begin
            $display("Time %0t: Failed load tc check. Expected 0, got %b", $time, tc);
            errors = errors + 1;
        end

        // Now decrement: load = 0 for 3 cycles
        load = 0;

        // Cycle 1 of countdown (count becomes 2)
        @(posedge clk); #1;
        if (tc !== 1'b0) errors = errors + 1;

        // Cycle 2 of countdown (count becomes 1)
        @(posedge clk); #1;
        if (tc !== 1'b0) errors = errors + 1;

        // Cycle 3 of countdown (count becomes 0)
        @(posedge clk); #1;
        if (tc !== 1'b1) begin
            $display("Time %0t: Terminal count not reached. Expected tc=1, got %b", $time, tc);
            errors = errors + 1;
        end

        // Verify it stays at 0 and tc stays 1
        @(posedge clk); #1;
        if (tc !== 1'b1) errors = errors + 1;

        // Test 2: Reload while counting (interrupt countdown)
        // Load 2
        load = 1;
        data = 10'd2;
        @(posedge clk); #1;
        if (tc !== 1'b0) errors = errors + 1;

        // Count 1 cycle (count becomes 1)
        load = 0;
        @(posedge clk); #1;
        if (tc !== 1'b0) errors = errors + 1;

        // Before reaching 0, reload with 5
        load = 1;
        data = 10'd5;
        @(posedge clk); #1;
        if (tc !== 1'b0) errors = errors + 1;

        // Count down 5 cycles
        load = 0;
        repeat (4) begin
            @(posedge clk); #1;
            if (tc !== 1'b0) errors = errors + 1;
        end

        // 5th cycle should hit 0
        @(posedge clk); #1;
        if (tc !== 1'b1) begin
            $display("Time %0t: Reload countdown failed. Expected tc=1, got %b", $time, tc);
            errors = errors + 1;
        end

        // Final Result Display
        #20;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

