    integer i;
    reg [31:0] expected_q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to compute expected next state for a 32-bit Galois LFSR
    // with taps at positions 32, 22, 2, 1 (using 0-indexed bit positions 31, 21, 1, 0).
    // In standard Galois LFSR:
    // If output bit (bit 31) is 1, feed back into taps (31, 21, 1, 0) XORed with 1.
    // Specifically:
    // next_q[0] = q[31]
    // next_q[k] = q[k-1] ^ (q[31] & tap[k]) for k > 0
    // Taps at 31, 21, 1, 0.
    function [31:0] galois_lfsr_step;
        input [31:0] current;
        reg feed;
        begin
            feed = current[31];
            galois_lfsr_step[0] = feed;
            galois_lfsr_step[1] = current[0] ^ feed;
            galois_lfsr_step[2] = current[1] ^ feed;
            for (i = 3; i <= 21; i = i + 1) begin
                galois_lfsr_step[i] = current[i-1];
            end
            galois_lfsr_step[22] = current[21] ^ feed;
            for (i = 23; i <= 31; i = i + 1) begin
                galois_lfsr_step[i] = current[i-1];
            end
        end
    endfunction

    initial begin
        clk = 0;
        reset = 0;

        // Test 1: Reset behavior
        // Apply reset asynchronously/synchronously and check state becomes 32'h1 on posedge clk
        reset = 1;
        #12;
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Check value immediately after reset release (should still be 32'h1 or transition)
        expected_q = 32'h1;

        // Step through multiple clock cycles and verify LFSR transitions
        for (i = 0; i < 20; i = i + 1) begin
            // Compute expected state for the upcoming clock edge
            expected_q = galois_lfsr_step(expected_q);

            @(posedge clk);
            #1; // small delay to allow output to settle after clock edge

            if (q !== expected_q) begin
                errors = errors + 1;
            end
        end

        // Test 2: Synchronous reset assertion mid-stream
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== expected_q) begin // before clock edge, q shouldn't change yet if synchronous
            // Wait, synchronous reset takes effect on posedge clk
        end

        @(posedge clk);
        #1;
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        // Release reset again
        reset = 0;
        expected_q = 32'h1;

        // Run a few more cycles post-reset
        for (i = 0; i < 5; i = i + 1) begin
