module tb;
    reg clk;
    reg areset;
    reg load;
    reg ena;
    reg [3:0] data;
    wire [3:0] q;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    initial begin
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;

        // Test 1: Asynchronous Reset (assert asynchronously, verify immediate clear)
        #2;
        areset = 1;
        #3;
        if (q !== 4'b0000) errors = errors + 1;

        #5;
        areset = 0;
        #2;
        if (q !== 4'b0000) errors = errors + 1;

        // Test 2: Synchronous Load
        @(posedge clk);
        data = 4'b1011;
        load = 1;
        ena = 0;
        @(posedge clk);
        #1;
        if (q !== 4'b1011) errors = errors + 1;

        // Test 3: Synchronous Enable (Right Shift)
        // q was 4'b1011. Shifting right should make q -> {1'b0, q[3:1]} => {1'b0, 4'b101} = 4'b0101
        load = 0;
        ena = 1;
        @(posedge clk);
        #1;
        if (q !== 4'b0101) errors = errors + 1;

        // Shift again: {1'b0, 4'b010} = 4'b0010
        @(posedge clk);
        #1;
        if (q !== 4'b0010) errors = errors + 1;

        // Test 4: Priority check - load and ena both asserted (load should win)
        data = 4'b1110;
        load = 1;
        ena = 1;
        @(posedge clk);
        #1;
        if (q !== 4'b1110) errors = errors + 1;

        // Test 5: No operation (load=0, ena=0) -> retain value
        load = 0;
        ena = 0;
        data = 4'b0001; // should be ignored
        @(posedge clk);
        #1;
        if (q !== 4'b1110) errors = errors + 1;

        // Test 6: Asynchronous reset overriding active clock edge/load/ena
        load = 1;
        data = 4'b1111;
        #2;
        areset = 1;
        #3;
        if (q !== 4'b0000) errors = errors + 1;
        areset = 0;

        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

