`timescale 1ns/1ps

module tb;
    reg clk;
    reg areset;
    reg load;
    reg ena;
    reg [3:0] data;
    wire [3:0] q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Self-checking task
    task check_q(input [3:0] expected);
        begin
            @(posedge clk);
            #1; // Wait for output to settle
            if (q !== expected) begin
                $display("Time %0t: Mismatch! Expected q = %b, Got q = %b (areset=%b, load=%b, ena=%b, data=%b)",
                         $time, expected, q, areset, load, ena, data);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;

        // Test 1: Asynchronous Reset (assert during low clock, check immediate zero)
        #2;
        areset = 1;
        #3;
        if (q !== 4'b0000) begin
            $display("Time %0t: Async reset failed! Got q = %b", $time, q);
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        #5;

        // Test 2: Synchronous Load
        @(posedge clk);
        load = 1;
        ena = 0;
        data = 4'b1010;
        check_q(4'b1010); // After posedge, q should be 4'b1010

        // Test 3: Hold state when load=0 and ena=0
        load = 0;
        ena = 0;
        check_q(4'b1010); // Should remain 4'b1010

        // Test 4: Shift Right (ena=1)
        // 4'b1010 shifted right -> 4'b0101 (since q[3] becomes 0)
        ena = 1;
        check_q(4'b0101);

        // Shift right again -> 4'b0010
        check_q(4'b0010);

        // Shift right again -> 4'b0001
        check_q(4'b0001);

        // Shift right again -> 4'b0000
        check_q(4'b0000);

        // Test 5: Priority Test - load and ena both asserted (load should have higher priority)
        load = 1;
        ena = 1;
        data = 4'b1100;
        check_q(4'b1100); // Should load data, not shift

        // Test 6: Verify shifting resumes after priority load when load=0, ena=1
        load = 0;
        ena = 1;
        check_q(4'b0110);

        // Test 7: Synchronous Reset check (Wait, specification says "asynchronous positive edge triggered areset". Let's test areset again properly).
        areset = 1;
        #2;
        if (q !== 4'b0000) begin
            $display("Time %0t: Async reset active check failed! Got q = %b", $time, q);
            errors = errors + 1;
        end
        areset = 0;
        #3;

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

