module tb;
    reg clk;
    reg reset;
    wire [4:0] q;

    // Instantiate the DUT exactly as required
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    integer cycle_count = 0;
    reg [4:0] expected_q;

    // Function to compute next expected state of a 5-bit Galois LFSR with taps at 5 and 3 (1-indexed)
    // In 0-indexed terms (bits 4 down to 0): taps at positions 4 and 2.
    // Galois LFSR shift/XOR rule:
    // New bit [4] = old bit [0]
    // New bit [3] = old bit [4]
    // New bit [2] = old bit [3] ^ old bit [0] (tap at position 2 corresponds to bit 2)
    // New bit [1] = old bit [2]
    // New bit [0] = old bit [1] ^ old bit [0] (tap at position 4 corresponds to bit 0)
    function [4:0] lfsr_next;
        input [4:0] current;
        reg out_bit;
        begin
            out_bit = current[0];
            lfsr_next[4] = out_bit;
            lfsr_next[3] = current[4];
            lfsr_next[2] = current[3] ^ out_bit;
            lfsr_next[1] = current[2];
            lfsr_next[0] = current[1] ^ out_bit;
        end
    endfunction

    initial begin
        // Initialize inputs
        reset = 1;

        // Wait for a couple of clock edges under reset
        @(posedge clk);
        @(posedge clk);

        // Check reset state: should be 5'b00001 (or decimal 1, per spec "reset the LFSR output to 1")
        // Let's verify output immediately after rising edge
        #1;
        if (q !== 5'b00001) begin
            $display("ERROR: Reset failed. Expected 5'b00001, got %b", q);
            errors = errors + 1;
        end

        // Deassert reset
        @(negedge clk);
        reset = 0;

        // Track and check expected sequence for 35 cycles (maximal length is 2^5 - 1 = 31 states)
        expected_q = 5'b00001; // Current state after reset

        repeat (35) begin
            @(posedge clk);
            #1; // small delay for propagation

            // Compute what the next state SHOULD be based on golden model
            expected_q = lfsr_next(expected_q);

            // 4-State Output Equality check using !==
            if (q !== expected_q) begin
                $display("ERROR at cycle %0d: Expected q = %b, got q = %b", cycle_count, expected_q, q);
                errors = errors + 1;
            end

            // Also check that it never hits 0's
            if (q === 5'b00000) begin
                $display("ERROR: LFSR entered all-zero state!");
                errors = errors + 1;
            end

            cycle_count = cycle_count + 1;
        end

        // Test synchronous reset mid-stream
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 5'b00001) begin
            $display("ERROR: Mid-stream synchronous reset failed. Got %b", q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

