`timescale 1ns/1ps

module tb;
    reg clk;
    reg areset;
    reg x;
    wire z;

    // Instantiate the DUT exactly as specified
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Task to check output against expected value using case inequality (`!==`)
    task check_output;
        input [0:0] expected_z;
        begin
            @(posedge clk);
            #1; // Small delay to allow combinational output to settle after clock edge
            if (z !== expected_z) begin
                $display("Time %0t: Mismatch! x=%b, z=%b, expected_z=%b", $time, x, z, expected_z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 1;
        x = 0;

        // Test 1: Asynchronous Reset check
        #12;
        if (z !== 1'b0) begin
            $display("Time %0t: Reset error! z=%b, expected 0", $time, z);
            errors = errors + 1;
        end

        // Release reset
        areset = 0;
        @(posedge clk);

        // Test 2: FSM transitions starting from State A (after reset)
        // Specification:
        // A --x=0 (z=0)-> A
        // A --x=1 (z=1)-> B
        // B --x=0 (z=1)-> B
        // B --x=1 (z=0)-> B

        // In State A: apply x=0 -> expect z=0, stay in A
        x = 0;
        check_output(1'b0);

        // In State A: apply x=0 -> expect z=0, stay in A
        x = 0;
        check_output(1'b0);

        // In State A: apply x=1 -> expect z=1, transition to B
        x = 1;
        check_output(1'b1);

        // Now in State B: apply x=0 -> expect z=1, stay in B
        x = 0;
        check_output(1'b1);

        // In State B: apply x=1 -> expect z=0, stay in B
        x = 1;
        check_output(1'b0);

        // In State B: apply x=1 -> expect z=0, stay in B
        x = 1;
        check_output(1'b0);

        // In State B: apply x=0 -> expect z=1, stay in B
        x = 0;
        check_output(1'b1);

        // Test 3: Asynchronous Reset recovery during operation
        areset = 1;
        #3;
        if (z !== 1'b0) begin
            $display("Time %0t: Asynchronous reset activation error! z=%b", $time, z);
            errors = errors + 1;
        end

        areset = 0;
        x = 1;
        check_output(1'b1); // Should be back in A, taking x=1 to B (z=1)

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

