module tb;
    reg clk;
    reg areset;
    reg x;
    wire z;

    // Instantiate the DUT exactly as required
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg expected_z;

    // Task to apply inputs and check outputs synchronously
    task apply_and_check(input new_x, input exp_z);
        begin
            @(posedge clk);
            #1; // Small delay to allow combinatorial/sequential updates to settle
            x = new_x;
            expected_z = exp_z;
            #4; // Wait near edge or mid-cycle
            if (z !== expected_z) begin
                $display("Mismatch at time %0t: x = %b, expected z = %b, got z = %b", $time, x, expected_z, z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Test 1: Asynchronous active-high reset check
        // Assert reset asynchronously
        areset = 1;
        #3;
        if (z !== 1'b0) begin
            $display("Mismatch during async reset: expected z = 0, got z = %b", z);
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        #7;

        // FSM Behavioral Test (2's complementer starting from State A):
        // State A: seeing 0s keeps us in A (z=0). Seeing first 1 transitions to B and outputs 1 (z=1).
        // State B: seeing 0 outputs 1 (z=1), seeing 1 outputs 0 (z=0), stays in B.

        // Sequence: x = 0 (A -> A, z = 0)
        apply_and_check(1'b0, 1'b0);

        // Sequence: x = 0 (A -> A, z = 0)
        apply_and_check(1'b0, 1'b0);

        // Sequence: x = 1 (A -> B, z = 1) - First '1' encountered
        apply_and_check(1'b1, 1'b1);

        // Sequence: x = 0 (B -> B, z = 1) - Inverted bit after first '1'
        apply_and_check(1'b0, 1'b1);

        // Sequence: x = 1 (B -> B, z = 0) - Inverted bit after first '1'
        apply_and_check(1'b1, 1'b0);

        // Sequence: x = 0 (B -> B, z = 1)
        apply_and_check(1'b0, 1'b1);

        // Test asynchronous reset mid-stream
        @(posedge clk);
        areset = 1;
        #2;
        if (z !== 1'b0) begin
            $display("Mismatch during mid-stream async reset: expected z = 0, got z = %b", z);
            errors = errors + 1;
        end
        areset = 0;
        #3;

        // Verify back in state A after reset: x = 1 should give z = 1
        apply_and_check(1'b1, 1'b1);
        // In state B now: x = 1 should give z = 0
        apply_and_check(1'b1, 1'b0);

        // Final evaluation and result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

