    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Task to apply inputs and check expected output
    task apply_and_check(input reg new_x, input reg expected_z);
        begin
            x = new_x;
            @(posedge clk);
            #1; // small delay to allow combinatorial/sequential update
            if (z !== expected_z) begin
                $display("Time %0t: Mismatch! x=%b, expected z=%b, got z=%b", $time, new_x, expected_z, z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        clk = 0;
        areset = 0;
        x = 0;

        // Test 1: Asynchronous Reset check
        // Assert reset asynchronously
        areset = 1;
        #3;
        if (z !== 1'b0) begin
            $display("Time %0t: Reset error! z should be 0 during areset", $time);
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        @(posedge clk);
        #1;
        if (z !== 1'b0) begin
            $display("Time %0t: Reset release error! z should be 0 in State A", $time);
            errors = errors + 1;
