        // Test 2: FSM functionality (2's complementer sequence)
        // State A: x=0 -> z=0, stays A
        apply_and_check(0, 0);
        apply_and_check(0, 0);

        // State A: x=1 -> z=1, transitions to B
        apply_and_check(1, 1);

        // State B: x=0 -> z=1, stays B
        apply_and_check(0, 1);
        apply_and_check(0, 1);

        // State B: x=1 -> z=0, stays B
        apply_and_check(1, 0);
        apply_and_check(1, 0);

        // State B: x=0 -> z=1, stays B
        apply_and_check(0, 1);

