        areset = 0;
        @(posedge clk);
        #1;

        // Back in State A, verify sequence again
        // x=1 -> z=1 (State B)
        apply_and_check(1, 1);
        // x=1 -> z=0 (State B)
        apply_and_check(1, 0);

        // Final result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

