module TopModule (
    input  clk,
    input  areset,
    input  x,
    output reg z
);

    reg [1:0] state; // State variable to track the current state
    reg [1:0] next_state; // Next state variable
    reg [31:0] result; // Register to hold the 2's complement result
    reg [4:0] bit_count; // Counter for the number of bits processed

    // State encoding
    localparam IDLE = 2'b00;
    localparam PROCESS = 2'b01;
    localparam OUTPUT = 2'b10;

    // Sequential logic for state transitions
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= IDLE;
            result <= 0;
            bit_count <= 0;
            z <= 0;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic for next state and output
    always @(*) begin
        case (state)
            IDLE: begin
                if (!areset) begin
                    next_state = PROCESS;
                    bit_count = 0;
                end else begin
                    next_state = IDLE;
                end
            end

            PROCESS: begin
                if (bit_count < 32) begin
                    result[bit_count] = x; // Capture the input bit
                    bit_count = bit_count + 1;
                    next_state = PROCESS;
                end else begin
                    next_state = OUTPUT; // Move to output state after capturing all bits
                end
            end

            OUTPUT: begin
                z = ~result + 1; // Compute 2's complement
                next_state = IDLE; // Return to IDLE state
            end

            default: begin
                next_state = IDLE; // Default state
            end
        endcase
    end

endmodule

