        apply_reset();

        // Feed bits: LSB first for 4'b0110 -> x = 0, 1, 1, 0
        // But candidate waits for 32 bits! If we stop at 4 bits, it will never transition to COMPLEMENT.
        // Let's feed 32 zeros first to satisfy `bit_count == 31`.
        for (i = 0; i < 32; i = i + 1) begin
            @(posedge clk);
            x = 0;
        end

        // Now it should enter COMPLEMENT and OUTPUT states.
        // Let's observe output behavior.
