        // B (000010): w=0 -> D(001000), w=1 -> C(000100) => Y1_next = 0, Y3_next = 0
        // C (000100): w=0 -> D(001000), w=1 -> E(010000) => Y1_next = 0, Y3_next = 0
        // D (001000): w=0 -> A(000001), w=1 -> F(100000) => Y1_next = 0, Y3_next = 1
        // E (010000): w=0 -> D(001000), w=1 -> E(010000) => Y1_next = 1, Y3_next = 0
        // F (100000): w=0 -> D(001000), w=1 -> C(000100) => Y1_next = 1, Y3_next = 0

