`timescale 1ns/1ps

module tb;
    reg [5:0] y;
    reg       w;
    wire      Y1;
    wire      Y3;

    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;
    integer i;

    initial begin
        // Test all possible state values (0 to 63) and both w values (0 and 1)
        // to expose bugs in state transitions, output mappings, and invalid states.
        for (i = 0; i < 64; i = i + 1) begin
            y = i[5:0];
            w = 1'b0;
            #1;
            check_outputs();

            w = 1'b1;
            #1;
            check_outputs();
        end

        // Check test result status
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    // Task to verify expected behavior against spec
    // Spec:
    // y[0]=A, y[1]=B, y[2]=C, y[3]=D, y[4]=E, y[5]=F
    // FSM transitions (Next State Logic):
    // A(000001): w=0 -> A(000001), w=1 -> B(000010)
    // B(000010): w=0 -> D(001000), w=1 -> C(000100)
    // C(000100): w=0 -> D(001000), w=1 -> E(010000)
    // D(001000): w=0 -> A(000001), w=1 -> F(100000)
    // E(010000): w=0 -> D(001000), w=1 -> E(010000)
    // F(100000): w=0 -> D(001000), w=1 -> C(000100)
    //
    // Since Y1 is the input to state flip-flop y[1] (bit 1 of next state),
    // and Y3 is the input to state flip-flop y[3] (bit 3 of next state),
    // Y1 should be 1 if and only if the NEXT state has y[1]=1 (State B).
    // Y3 should be 1 if and only if the NEXT state has y[3]=1 (State D).
    //
    // Let's check candidate RTL:
    // candidate assigns Y1 based purely on CURRENT state: y[1] ? 1 : 0
    // candidate assigns Y3 based purely on CURRENT state: y[3] ? 1 : 0
    // But the prompt states: "The output signal Y1 should be the input of state flip-flop y[1]. The output signal Y3 should be the input of state flip-flop y[3]."
    // In synchronous sequential circuits with one-hot encoding, Y1/Y3 represent the next-state logic equations for those bits!
    // Let's see what the candidate RTL actually implemented:
    // It implemented Y1 = y[1] and Y3 = y[3] (identity/current state buffer), which completely ignores the FSM next-state transition rules!
    // Our testbench will assert expected next-state bit values for Y1 and Y3.

    function [1:0] get_expected_next_bits(input [5:0] curr_y, input curr_w);
        reg [5:0] next_y;
        begin
            next_y = 6'b0;
            case (curr_y)
                6'b000001: next_y = curr_w ? 6'b000010 : 6'b000001; // A -> B or A
                6'b000010: next_y = curr_w ? 6'b000100 : 6'b001000; // B -> C or D
                6'b000100: next_y = curr_w ? 6'b010000 : 6'b001000; // C -> E or D
                6'b001000: next_y = curr_w ? 6'b100000 : 6'b000001; // D -> F or A
                6'b010000: next_y = curr_w ? 6'b010000 : 6'b001000; // E -> E or D
                6'b100000: next_y = curr_w ? 6'b000100 : 6'b001000; // F -> C or D
                default:   next_y = 6'b000000;
            endcase
            get_expected_next_bits = {next_y[3], next_y[1]}; // {Y3, Y1}
        end
    endfunction

    task check_outputs();
        reg [1:0] exp;
        begin
            exp = get_expected_next_bits(y, w);
            // Use case inequality !== as per rule 9
            if (Y3 !== exp[1] || Y1 !== exp[0]) begin
                $display("Mismatched at y=%b, w=%b: got Y3=%b Y1=%b, expected Y3=%b Y1=%b", 
                         y, w, Y3, Y1, exp[1], exp[0]);
                errors = errors + 1;
            end
        end
    endtask

endmodule

