`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg [5:0] y;
    reg       w;
    wire      Y1;
    wire      Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;
    integer i, j;
    reg [5:0] expected_y;
    reg expected_Y1;
    reg expected_Y3;

    // Task to calculate expected next-state logic (Y1 and Y3)
    // based on one-hot FSM transitions given in spec:
    // A (000001): --1--> B, --0--> A
    // B (000010): --1--> C, --0--> D
    // C (000100): --1--> E, --0--> D
    // D (001000): --1--> F, --0--> A
    // E (010000): --1--> E, --0--> D
    // F (100000): --1--> C, --0--> D
    //
    // Next state mapping:
    // A_next = (A & ~w) + (D & ~w) + (E & ~w) + (F & ~w) -> Wait, let's trace exact state transitions:
    // If w=0:
    // A -> A (y[0])
    // B -> D (y[3])
    // C -> D (y[3])
    // D -> A (y[0])
    // E -> D (y[3])
    // F -> D (y[3])
    //
    // If w=1:
    // A -> B (y[1])
    // B -> C (y[2])
    // C -> E (y[4])
    // D -> F (y[5])
    // E -> E (y[4])
    // F -> C (y[2])
    //
    // Let's summarize next-state bits for y[1] (Y1) and y[3] (Y3):
    // Y1 (next state is B):
    // - From A with w=1 => A & w
    //
    // Y3 (next state is D):
    // - From B with w=0 => B & ~w
    // - From C with w=0 => C & ~w
    // - From E with w=0 => E & ~w
    // - From F with w=0 => F & ~w
    // So Y3 = (B | C | E | F) & ~w
    // And Y1 = A & w

    initial begin
        errors = 0;

        // Test all combinations of one-hot states and w inputs
        // Valid one-hot states: y = 6'b000001, 6'b000010, 6'b000100, 6'b001000, 6'b010000, 6'b100000
        for (i = 0; i < 64; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                y = i[5:0];
                w = j[0];
                #5;

                // Determine expected Y1
                // Y1 is 1 only when state is A (y[0]) and w is 1
                expected_Y1 = (y == 6'b000001) && (w == 1'b1);

                // Determine expected Y3
                // Y3 is 1 when state is B, C, E, or F and w is 0
                expected_Y3 = ((y == 6'b000010) || 
                               (y == 6'b000100) || 
                               (y == 6'b010000) || 
                               (y == 6'b100000)) && (w == 1'b0);

                // Use case inequality (`!==`) for robust 4-state checking
                if (Y1 !== expected_Y1) begin
                    errors = errors + 1;
                end

                if (Y3 !== expected_Y3) begin
                    errors = errors + 1;
                end
            end
        end

        // Additional edge case: unassigned / X / Z inputs
        y = 6'bxxxxxx;
        w = 1'bx;
        #5;
        // We just ensure it doesn't crash simulation, but we won't strictly assert value 
        // since implementation details vary, though 4-state check handles it.

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

