module tb;
    reg [5:0] y_in;
    reg       w_in;
    wire      Y1_out;
    wire      Y3_out;

    integer errors = 0;

    // Instantiate the DUT
    TopModule dut (
        .y(y_in),
        .w(w_in),
        .Y1(Y1_out),
        .Y3(Y3_out)
    );

    initial begin
        // Adversarial test cases: probing boundary conditions, illegal one-hot states, 
        // and checking if candidate RTL actually implements the FSM transitions or just simple passthroughs.

        // FSM Specification check:
        // A (000001) --0--> A (y[0]=1)
        // A (000001) --1--> B (y[1]=1) -> Y1 should be next state bit y[1]
        // B (000010) --1--> C (y[2]=1)
        // B (000010) --0--> D (y[3]=1) -> Y3 should be next state bit y[3]
        // C (000100) --1--> E (y[4]=1)
        // C (000100) --0--> D (y[3]=1) -> Y3 should be next state bit y[3]
        // D (001000) --1--> F (y[5]=1)
        // D (001000) --0--> A (y[0]=1)
        // E (010000) --1--> E (y[4]=1)
        // E (010000) --0--> D (y[3]=1) -> Y3 should be next state bit y[3]
        // F (100000) --1--> C (y[2]=1)
        // F (100000) --0--> D (y[3]=1) -> Y3 should be next state bit y[3]

        // NOTE: The candidate RTL implements:
        // assign Y1 = y[1];
        // assign Y3 = y[3];
        // This is a direct passthrough of current state bits rather than the next-state logic!
        // Let's test if Y1 and Y3 depend on `w` or just mirror current state.

        // Test 1: State A (000001), w=1 -> should go to B (so Y1 should be 1, Y3 should be 0)
        y_in = 6'b000001;
        w_in = 1'b1;
        #10;
        // Expected from FSM next state: Y1=1, Y3=0.
        // Candidate RTL gives: Y1 = y[1] = 0, Y3 = y[3] = 0.
        if (Y1_out !== 1'b1) begin
            $display("BUG EXPOSED: State A with w=1 expected Y1=1 (transition to B), got Y1=%b", Y1_out);
            errors = errors + 1;
        end

        // Test 2: State B (000010), w=0 -> should go to D (so Y3 should be 1, Y1 should be 0)
        y_in = 6'b000010;
        w_in = 1'b0;
        #10;
        // Expected from FSM next state: Y1=0, Y3=1.
        // Candidate RTL gives: Y1 = y[1] = 1, Y3 = y[3] = 0.
        if (Y3_out !== 1'b1) begin
            $display("BUG EXPOSED: State B with w=0 expected Y3=1 (transition to D), got Y3=%b", Y3_out);
            errors = errors + 1;
        end
        if (Y1_out !== 1'b0) begin
            $display("BUG EXPOSED: State B with w=0 expected Y1=0, got Y1=%b", Y1_out);
            errors = errors + 1;
        end

        // Test 3: Illegal/Unused one-hot states (e.g. 6'b000000, 6'b111111)
        y_in = 6'b111111;
        w_in = 1'b1;
        #10;
        if (Y1_out !== 1'b0 || Y3_out !== 1'b0) begin
            // Depending on design, but let's check strict 4-state inequality handling
            // Just exercising the testbench contract requirement using !==
            $display("Info: Handled illegal state vector 6'b111111 cleanly.");
        end

        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

