`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg [5:0] y;
    reg w;
    wire Y1;
    wire Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;

    // Task to check outputs against expected values
    task check_outputs(input [5:0] current_y, input current_w, input exp_Y1, input exp_Y3);
        begin
            y = current_y;
            w = current_w;
            #1; // Allow combinational propagation
            if (Y1 !== exp_Y1) begin
                $display("Mismatch: y=6'b%b, w=%b | Expected Y1=%b, Got Y1=%b", current_y, current_w, exp_Y1, Y1);
                errors = errors + 1;
            end
            if (Y3 !== exp_Y3) begin
                $display("Mismatch: y=6'b%b, w=%b | Expected Y3=%b, Got Y3=%b", current_y, current_w, exp_Y3, Y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // FSM State transitions & output logic derivation check:
        // One-hot state encoding:
        // A = 6'b000001 (y[0])
        // B = 6'b000010 (y[1])
        // C = 6'b000100 (y[2])
        // D = 6'b001000 (y[3])
        // E = 6'b010000 (y[4])
        // F = 6'b100000 (y[5])

        // Transitions & Next-State equations:
        // Next State A (y[0]): from D when w=0, or A when w=0.
        // Next State B (y[1]): from A when w=1.  --> Y1 = y[0] & w
        // Next State C (y[2]): from B when w=1, or F when w=1.
        // Next State D (y[3]): from B when w=0, C when w=0, E when w=0, F when w=0. --> Y3 = (y[1] | y[2] | y[4] | y[5]) & ~w
        // Next State E (y[4]): from C when w=1, or E when w=1.
        // Next State F (y[5]): from D when w=1.

        // Test vectors covering all states and input combinations (w=0 and w=1)

        // State A (6'b000001)
        check_outputs(6'b000001, 1'b0, 1'b0, 1'b0); // w=0 -> A
        check_outputs(6'b000001, 1'b1, 1'b1, 1'b0); // w=1 -> B (Y1 should be 1)

        // State B (6'b000010)
        check_outputs(6'b000010, 1'b0, 1'b0, 1'b1); // w=0 -> D (Y3 should be 1)
        check_outputs(6'b000010, 1'b1, 1'b0, 1'b0); // w=1 -> C

        // State C (6'b000100)
        check_outputs(6'b000100, 1'b0, 1'b0, 1'b1); // w=0 -> D (Y3 should be 1)
        check_outputs(6'b000100, 1'b1, 1'b0, 1'b0); // w=1 -> E

        // State D (6'b001000)
        check_outputs(6'b001000, 1'b0, 1'b0, 1'b0); // w=0 -> A
        check_outputs(6'b001000, 1'b1, 1'b0, 1'b0); // w=1 -> F

        // State E (6'b010000)
        check_outputs(6'b010000, 1'b0, 1'b0, 1'b1); // w=0 -> D (Y3 should be 1)
        check_outputs(6'b010000, 1'b1, 1'b0, 1'b0); // w=1 -> E

        // State F (6'b100000)
        check_outputs(6'b100000, 1'b0, 1'b0, 1'b1); // w=0 -> D (Y3 should be 1)
        check_outputs(6'b100000, 1'b1, 1'b0, 1'b0); // w=1 -> C

        // Edge case: Zero-hot and multi-hot states (robustness check)
        check_outputs(6'b000000, 1'b0, 1'b0, 1'b0);
        check_outputs(6'b111111, 1'b1, 1'b1, 1'b0);

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule

