`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    wire shift_ena;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer cycle_count;

    initial begin
        clk = 0;
        reset = 1;
        cycle_count = 0;

        // Apply reset and check reset behavior
        @(posedge clk);
        #1;
        // Spec: "Whenever the FSM is reset, assert shift_ena for 4 cycles, then 0 forever (until reset)."
        // Let's test the immediate cycle after reset deassertion.
        // Wait, let's look at the candidate RTL on reset:
        // shift_ena <= 1'b1; count <= 2'b00;
        // On the next 4 cycles (including the reset cycle or after?), let's trace:
        // Cycle 1 (reset=1): shift_ena becomes 1 (non-blocking, active on posedge).

        // Let's release reset and check 4 consecutive cycles of shift_ena = 1, followed by 0.
        reset = 0;

        // Cycle 1 of execution (count was 0 on reset, now increments to 1)
        @(posedge clk); #1;
        cycle_count = cycle_count + 1;
        if (shift_ena !== 1'b1) begin
            $display("Error at cycle %0d: expected shift_ena to be 1, got %b", cycle_count, shift_ena);
            errors = errors + 1;
        end

        // Cycle 2 (count increments to 2)
        @(posedge clk); #1;
        cycle_count = cycle_count + 1;
        if (shift_ena !== 1'b1) begin
            $display("Error at cycle %0d: expected shift_ena to be 1, got %b", cycle_count, shift_ena);
            errors = errors + 1;
        end

        // Cycle 3 (count increments to 3)
        @(posedge clk); #1;
        cycle_count = cycle_count + 1;
        if (shift_ena !== 1'b1) begin
            $display("Error at cycle %0d: expected shift_ena to be 1, got %b", cycle_count, shift_ena);
            errors = errors + 1;
        end

        // Cycle 4 (count is 3, hits 'else' branch -> shift_ena <= 0)
        @(posedge clk); #1;
        cycle_count = cycle_count + 1;
        if (shift_ena !== 1'b1) begin
            $display("Error at cycle %0d (4th cycle): expected shift_ena to be 1, got %b", cycle_count, shift_ena);
            errors = errors + 1;
        end

        // Cycle 5 (should be 0 forever)
        @(posedge clk); #1;
        cycle_count = cycle_count + 1;
        if (shift_ena !== 1'b0) begin
            $display("Error at cycle %0d (5th cycle): expected shift_ena to be 0, got %b", cycle_count, shift_ena);
            errors = errors + 1;
        end

        // Cycle 6 (should remain 0)
        @(posedge clk); #1;
        cycle_count = cycle_count + 1;
        if (shift_ena !== 1'b0) begin
            $display("Error at cycle %0d (6th cycle): expected shift_ena to be 0, got %b", cycle_count, shift_ena);
            errors = errors + 1;
        end

        // Test mid-run reset
        reset = 1;
        @(posedge clk); #1;
        reset = 0;

        // Check if it restarts the 4-cycle sequence properly
        repeat (4) begin
            @(posedge clk); #1;
            if (shift_ena !== 1'b1) begin
                $display("Error during mid-run reset check: expected shift_ena to be 1");
                errors = errors + 1;
            end
        end

        @(posedge clk); #1;
        if (shift_ena !== 1'b0) begin
            $display("Error post mid-run reset: expected shift_ena to be 0");
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

