`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    wire shift_ena;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer cycle = 0;

    // Task to check output against expected value using case inequality (`!==`)
    task check_output(input expected);
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
            cycle = cycle + 1;
            if (shift_ena !== expected) begin
                $display("Time %0t: Mismatch! Expected shift_ena=%b, Got shift_ena=%b (Cycle %0d)", 
                         $time, expected, shift_ena, cycle);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        clk = 0;
        reset = 0;

        // Test 1: Reset behavior on startup (Active high synchronous reset).
        // Specification: "Whenever the FSM is reset, assert shift_ena for 4 cycles, then 0 forever"
        // Let's assert reset at cycle 1.
        @(posedge clk);
        reset = 1;

        // Check 4 cycles of active shift_ena while reset is held high (or applied)
        // Wait, specification says: "Whenever the FSM is reset, assert shift_ena for 4 cycles, then 0 forever (until reset)."
        // Let's verify if reset being held high keeps it asserting or if it starts the 4-cycle sequence.
        // Usually, synchronous reset initializes the FSM state. Let's see how the DUT handles it.
        // We will check 4 consecutive clock cycles where shift_ena should be 1 after reset assertion.

        // Cycle 1 under reset
        #1;
        if (shift_ena !== 1'b1) begin
            $display("Time %0t: Reset cycle 1 error: expected shift_ena=1, got %b", $time, shift_ena);
            errors = errors + 1;
        end

        // Deassert reset after 1 cycle to allow the 4-cycle counter to run, or keep it high?
        // "Whenever the FSM is reset, assert shift_ena for 4 cycles, then 0 forever (until reset)."
        // Let's test releasing reset and observing the 4 cycles.
        @(posedge clk);
        reset = 0;

        // We just had cycle 1 of reset. Let's trace the next cycles.
        // Let's do a clean test: Apply reset for 1 clock cycle, then release.
        // Expect exactly 4 cycles of shift_ena = 1 total.

        // Let's reset properly via a fresh pulse:
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        reset = 0;

        // Now we expect shift_ena to be 1 for exactly 4 cycles.
        check_output(1'b1); // Cycle 1
        check_output(1'b1); // Cycle 2
        check_output(1'b1); // Cycle 3
        check_output(1'b1); // Cycle 4

        // After 4 cycles, it should go to 0 forever until reset
        check_output(1'b0); // Cycle 5
        check_output(1'b0); // Cycle 6
        check_output(1'b0); // Cycle 7

        // Test 2: Apply reset again to verify it repeats the 4-cycle behavior
        @(posedge clk);
        reset = 1;
        #1;
        if (shift_ena !== 1'b1) begin
            $display("Time %0t: Second reset cycle 1 error", $time);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;

        check_output(1'b1); // Cycle 1
        check_output(1'b1); // Cycle 2
        check_output(1'b1); // Cycle 3
        check_output(1'b1); // Cycle 4
        check_output(1'b0); // Cycle 5
        check_output(1'b0); // Cycle 6

        // Final status report
        #20;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

