`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // Instantiate the DUT according to the contract
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Task to apply a single bit and check output
    task apply_bit(input bit val, input bit expected_out);
        begin
            data = val;
            @(posedge clk);
            #1; // small delay for propagation
            if (start_shifting !== expected_out) begin
                $display("Time %0t: Mismatch! data=%b, expected start_shifting=%b, got=%b", 
                         $time, val, expected_out, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        data = 0;

        // Test 1: Reset behavior
        #12;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset error! start_shifting is not 0", $time);
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        @(posedge clk);
        #1;

        // Test 2: Feed incorrect sequence, ensure start_shifting stays 0
        // Feed 1, 1, 1, 0 (should fail 1101 because of 1110)
        apply_bit(1, 0); // state S1
        apply_bit(1, 0); // state S2 (waiting for 0)
        apply_bit(1, 0); // received 1 instead of 0 -> resets to S1 (since data=1)
        apply_bit(0, 0); // from S1 with data=0 -> goes to S0
        apply_bit(1, 0); // back to S1

        // Test 3: Feed correct sequence: 1, 1, 0, 1
        // Currently we are at S1 (last bit fed was 1)
        // Let's reset cleanly to be sure about state
        reset = 1;
        @(posedge clk);
        #1;
        reset = 0;
        @(posedge clk);
        #1;

        if (start_shifting !== 1'b0) begin
            errors = errors + 1;
        end

        // Now feed exact sequence: 1, 1, 0, 1
        apply_bit(1, 0); // S0 -> S1
        apply_bit(1, 0); // S1 -> S2
        apply_bit(0, 0); // S2 -> S3
        apply_bit(1, 1); // S3 -> S4, start_shifting should become 1

        // Test 4: Verify latching / staying in S4 forever and ignoring further data
        apply_bit(0, 1);
        apply_bit(0, 1);
        apply_bit(1, 1);
        apply_bit(1, 1);

        // Test 5: Synchronous reset check while in S4
        reset = 1;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset from S4 failed to clear start_shifting", $time);
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

