        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset error! expected 0, got %b", $time, start_shifting);
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        @(posedge clk);
        #1;

        // Test 1: Idle / No match stream (0000)
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b0, 1'b0);

        // Test 2: Partial matches that fail (1110, 1100)
        apply_bit(1'b1, 1'b0); // 1
        apply_bit(1'b1, 1'b0); // 11
        apply_bit(1'b1, 1'b0); // 111 (fails sequence 1101)
        apply_bit(1'b0, 1'b0); // 1110 -> wait, 1110 contains last two as 10, not 01. Actually FSM resets or transitions correctly.
        apply_bit(1'b1, 1'b0); // 1
        apply_bit(1'b0, 1'b0); // 10
        apply_bit(1'b0, 1'b0); // 100 (fails)

        // Test 3: Successful sequence 1101
        apply_bit(1'b1, 1'b0); // 1
        apply_bit(1'b1, 1'b0); // 11
        apply_bit(1'b0, 1'b0); // 110
        apply_bit(1'b1, 1'b1); // 1101 -> FOUND! start_shifting should be 1

