`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    integer errors = 0;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to pulse clock
    task step;
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        data = 0;

        // Apply reset
        #12;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Release reset
        reset = 0;
        step();

        // Test case 1: Feed 1, 1, 0, 1 (Sequence found)
        // Feed first '1'
        data = 1;
        step();
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Feed second '1' (11)
        data = 1;
        step();
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Feed '0' (110)
        data = 0;
        step();
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Feed final '1' (1101)
        data = 1;
        step();
        // Here start_shifting should become 1
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test case 2: Check sticky behavior (stays 1 forever once found)
        data = 0; // change data to something else
        step();
        if (start_shifting !== 1'b1) errors = errors + 1;

        data = 1;
        step();
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test case 3: Synchronous reset test
        reset = 1;
        step();
        if (start_shifting !== 1'b0) errors = errors + 1;

        reset = 0;
        step();
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Test case 4: Overlapping sequences, e.g., 1101101
        data = 1; step();
        data = 1; step();
        data = 0; step();
        data = 1; step();
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Finish up
        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

