        S2 = 3'b010,
        S3 = 3'b011,
        S4 = 3'b100
    } state_t;

    state_t current_state, next_state;

    // State transition
    always @(posedge clk) begin
        if (reset) begin
            current_state <= S0;
            start_shifting <= 0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: begin
                if (data) next_state = S1; // 1
                else next_state = S0;
            end
            S1: begin
                if (data) next_state = S2; // 11
                else next_state = S0;
            end
            S2: begin
                if (data) next_state = S3; // 110
                else next_state = S0;
            end
            S3: begin
                if (data) begin
                    next_state = S4; // 1101
                    start_shifting = 1; // Set start_shifting
                end else begin
                    next_state = S0;
                end
            end
            S4: begin
                next_state = S4; // Stay in S4
            end
            default: next_state = S0;
        endcase
    end

endmodule

