module tb;
    reg  [6:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;
    reg [6:0] expected_Y1_map;
    reg [6:0] expected_Y3_map;

    // Task to check outputs using case inequality (!==) as per contract
    task check_outputs(input [6:0] exp1, input [6:0] exp3);
        begin
            #1; // Allow combinational propagation
            if (Y1 !== exp1) begin
                $display("Mismatch: y=%b, w=%b | Y1 = %b (Expected %b)", y, w, Y1, exp1);
                errors = errors + 1;
            end
            if (Y3 !== exp3) begin
                $display("Mismatch: y=%b, w=%b | Y3 = %b (Expected %b)", y, w, Y3, exp3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Adversarial & Boundary Testing:
        // 1. One-hot states A through F (represented via y[5:0])
        // State A: y[0]=1 (0000001)
        // State B: y[1]=1 (0000010)
        // State C: y[2]=1 (0000100)
        // State D: y[3]=1 (0001000)
        // State E: y[4]=1 (0010000)
        // State F: y[5]=1 (0100000)

        // Also testing illegal states, multiple hot bits (glitch/corruption), 
        // 7th bit active (y[6]), and all zeroes.

        // --- Test State A (y = 0000001) ---
        y = 7'b0000001; w = 0; check_outputs(1'b0, 1'b0); // A -> B (Y2=0, Y4=0)
        y = 7'b0000001; w = 1; check_outputs(1'b0, 1'b0); // A -> A (Y2=0, Y4=0)

        // --- Test State B (y = 0000010) ---
        y = 7'b0000010; w = 0; check_outputs(1'b1, 1'b0); // B -> C (Y2=1, Y4=0)
        y = 7'b0000010; w = 1; check_outputs(1'b0, 1'b1); // B -> D (Y2=0, Y4=1)

        // --- Test State C (y = 0000100) ---
        y = 7'b0000100; w = 0; check_outputs(1'b0, 1'b1); // C -> E (Y2=0, Y4=1)
        y = 7'b0000100; w = 1; check_outputs(1'b0, 1'b1); // C -> D (Y2=0, Y4=1)

        // --- Test State D (y = 00001000) ---
        y = 7'b0001000; w = 0; check_outputs(1'b0, 1'b0); // D -> F (Y2=0, Y4=0)
        y = 7'b0001000; w = 1; check_outputs(1'b0, 1'b0); // D -> A (Y2=0, Y4=0)

        // --- Test State E (y = 0010000) ---
        y = 7'b0010000; w = 0; check_outputs(1'b0, 1'b0); // E -> E (Y2=0, Y4=0)
        y = 7'b0010000; w = 1; check_outputs(1'b0, 1'b1); // E -> D (Y2=0, Y4=1)

        // --- Test State F (y = 0100000) ---
        y = 7'b0100000; w = 0; check_outputs(1'b1, 1'b0); // F -> C (Y2=1, Y4=0)
        y = 7'b0100000; w = 1; check_outputs(1'b0, 1'b1); // F -> D (Y2=0, Y4=1)

        // --- Adversarial Corner Cases / Illegal States ---
        // All zeros
        y = 7'b0000000; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b0000000; w = 1; check_outputs(1'b0, 1'b0);

        // Multiple hot bits (hammers state encoding)
        y = 7'b0111111; w = 0; check_outputs(1'b1, 1'b1); 
        y = 7'b0111111; w = 1; check_outputs(1'b1, 1'b1);

        // Out-of-range bit y[6] active
        y = 7'b1000000; w = 0; check_outputs(1'b0, 1'b0);
        y = 7'b1000000; w = 1; check_outputs(1'b0, 1'b0);

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

