module tb;
    reg  [6:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // Instantiate DUT according to the strict contract
    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;
    reg [6:0] expected_Y1;
    reg [6:0] expected_Y3;

    initial begin
        // Adversarial Test Vectors:
        // 1. One-hot states and all combinations of w (0 and 1)
        // State A: y = 7'b0000001 (y[0] active)
        // State B: y = 7'b0000010 (y[1] active)
        // State C: y = 7'b0000100 (y[2] active)
        // State D: y = 7'b00001000 (y[3] active)
        // State E: y = 7'b00010000 (y[4] active)
        // State F: y = 7'b00100000 (y[5] active)

        // Also test boundary/illegal conditions:
        // - All zeros
        // - Multiple bits hot (invalid one-hot)
        // - Unused bits in input y (y[6])

        // Test 1: State A (y = 6'b000001, plus y[6]=0), w=0
        y = 7'b0000001; w = 0; #10;
        // Expected from FSM spec: A--0-->B (y[1]), A--1-->A
        // Y1 is next-state for y[1]. In state A, w=0 leads to B (y[1]=1), w=1 leads to A (y[1]=0).
        // Let's check DUT implementation: 
        // assign Y1 = (y[1] & ~w) | (y[3] & ~w) | (y[5] & w);
        // For State A (y=1), Y1 should be 0. DUT gives 0.

        // Exhaustive check over valid one-hot states A through F
        // State A (y[0]=1)
        y = 7'b0000001; w = 0; #10; if (Y1 !== 1'b0 || Y3 !== 1'b0) errors++;
        y = 7'b0000001; w = 1; #10; if (Y1 !== 1'b0 || Y3 !== 1'b0) errors++;

        // State B (y[1]=1): B--0-->C(y[2]), B--1-->D(y[3])
        // Y1 (next y[1]) should be 0 for both w=0 and w=1.
        // Y3 (next y[3]) should be 0 for w=0, 1 for w=1 (goes to D).
        // Let's check DUT for State B (y[1]=1):
        // DUT Y1 = (1 & ~w) | ... => ~w. But state B on w=0 goes to C (y[2]), NOT B! 
        // Wait! Let's expose the bug in the candidate RTL!
        // Candidate RTL: assign Y1 = (y[1] & ~w) | (y[3] & ~w) | (y[5] & w);
        // If y[1]=1 and w=0, DUT Y1 = 1. This means next state has y[1]=1 (State B), but spec says B--0-->C!

        y = 7'b0000010; w = 0; #10; 
        // Spec: B --0--> C (y[2]). So y[1] next should be 0, y[3] next should be 0.
        // DUT Y1 for y[1]=1, w=0 -> 1 (BUG!).
        if (Y1 !== 1'b0) errors++; // This will fail and catch the bug!

        y = 7'b0000010; w = 1; #10;
        // Spec: B --1--> D (y[3]). y[1] next = 0, y[3] next = 1.
        if (Y3 !== 1'b1) errors++;

        // Test illegal / unused bit y[6]
        y = 7'b1000000; w = 0; #10;

        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule

