module tb;
    // Declare inputs as regs, outputs as wires
    reg [6:0] y;
    reg w;
    wire Y1;
    wire Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;

    // Task to check outputs against expected values
    task check_outputs(input [6:0] test_y, input test_w, input exp_Y1, input exp_Y3);
        begin
            y = test_y;
            w = test_w;
            #10; // Allow combinational logic to settle
            if (Y1 !== exp_Y1 || Y3 !== exp_Y3) begin
                $display("Mismatch: y = 7'b%b, w = %b | Got Y1=%b, Y3=%b | Expected Y1=%b, Y3=%b", 
                         test_y, test_w, Y1, Y3, exp_Y1, exp_Y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 7'b0000000;
        w = 1'b0;
        #10;

        // State Machine transitions and expected outputs based on specification:
        // One-hot state encoding:
        // A: y[5:0] = 000001 (y[6] unused/0)
        // B: y[5:0] = 000010
        // C: y[5:0] = 000100
        // D: y[5:0] = 001000
        // E: y[5:0] = 010000
        // F: y[5:0] = 100000
        //
        // Transitions:
        // A (000001) --0--> B (000010)
        // A (000001) --1--> A (000001)
        // B (000010) --0--> C (000100)
        // B (000010) --1--> D (001000)
        // C (000100) --0--> E (010000)
        // C (000100) --1--> D (001000)
        // D (001000) --0--> F (100000)
        // D (001000) --1--> A (000001)
        // E (010000) --0--> E (010000)
        // E (010000) --1--> D (001000)
        // F (100000) --0--> C (000100)
        // F (100000) --1--> D (001000)
        //
        // Outputs Y1 and Y3 correspond to next-state bit y[1] (state B) and y[3] (state D).

        // Test State A (7'b0000001)
        // w=0 -> Next is B (y[1]=1, y[3]=0) -> Y1=1, Y3=0
        check_outputs(7'b0000001, 1'b0, 1'b1, 1'b0);
        // w=1 -> Next is A (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0000001, 1'b1, 1'b0, 1'b0);

        // Test State B (7'b0000010)
        // w=0 -> Next is C (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0000010, 1'b0, 1'b0, 1'b0);
        // w=1 -> Next is D (y[1]=0, y[3]=1) -> Y1=0, Y3=1
        check_outputs(7'b0000010, 1'b1, 1'b0, 1'b1);

        // Test State C (7'b0000100)
        // w=0 -> Next is E (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0000100, 1'b0, 1'b0, 1'b0);
        // w=1 -> Next is D (y[1]=0, y[3]=1) -> Y1=0, Y3=1
        check_outputs(7'b0000100, 1'b1, 1'b0, 1'b1);

        // Test State D (7'b0001000)
        // w=0 -> Next is F (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0001000, 1'b0, 1'b0, 1'b0);
        // w=1 -> Next is A (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0001000, 1'b1, 1'b0, 1'b0);

        // Test State E (7'b0010000)
        // w=0 -> Next is E (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0010000, 1'b0, 1'b0, 1'b0);
        // w=1 -> Next is D (y[1]=0, y[3]=1) -> Y1=0, Y3=1
        check_outputs(7'b0010000, 1'b1, 1'b0, 1'b1);

        // Test State F (7'b0100000)
        // w=0 -> Next is C (y[1]=0, y[3]=0) -> Y1=0, Y3=0
        check_outputs(7'b0100000, 1'b0, 1'b0, 1'b0);
        // w=1 -> Next is D (y[1]=0, y[3]=1) -> Y1=0, Y3=1
        check_outputs(7'b0100000, 1'b1, 1'b0, 1'b1);

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

