        .in(in),
        .state(state),
        .next_state(next_state),
        .out(out)
    );

    integer errors = 0;

    // Task to check outputs against expected using 4-state case inequality
    task check;
        input [1:0] exp_next;
        input exp_out;
        begin
            #1; // allow combinational settling
            if (next_state !== exp_next || out !== exp_out) begin
                $display("Mismatch: state=%b, in=%b | got next_state=%b, out=%b | exp next_state=%b, exp out=%b",
