`timescale 1ns/1ps

module tb;
    reg in;
    reg [1:0] state;
    wire [1:0] next_state;
    wire out;

    integer errors = 0;
    integer i, s;

    // Instantiate TopModule dut
    TopModule dut (
        .in(in),
        .state(state),
        .next_state(next_state),
        .out(out)
    );

    // Expected values function based on the specification
    // State encoding: A=2'b00, B=2'b01, C=2'b10, D=2'b11
    // Table:
    // State | Next state (in=0, in=1) | Output
    // A     | A (00), B (01)          | 0
    // B     | C (10), B (01)          | 0
    // C     | A (00), D (11)          | 0
    // D     | C (10), B (01)          | 1
    function [2:0] get_expected;
        input [1:0] current_state;
        input input_val;
        begin
            casex ({current_state, input_val})
                3'b00_0: get_expected = {2'b00, 1'b0}; // A, in=0 -> next A, out 0
                3'b00_1: get_expected = {2'b01, 1'b0}; // A, in=1 -> next B, out 0
                3'b01_0: get_expected = {2'b10, 1'b0}; // B, in=0 -> next C, out 0
                3'b01_1: get_expected = {2'b01, 1'b0}; // B, in=1 -> next B, out 0
                3'b10_0: get_expected = {2'b00, 1'b0}; // C, in=0 -> next A, out 0
                3'b10_1: get_expected = {2'b11, 1'b0}; // C, in=1 -> next D, out 0
                3'b11_0: get_expected = {2'b10, 1'b1}; // D, in=0 -> next C, out 1
                3'b11_1: get_expected = {2'b01, 1'b1}; // D, in=1 -> next B, out 1
                default: get_expected = 3'bxx_x;
            endcase
        end
    endfunction

    reg [2:0] expected;

    initial begin
        // Apply exhaustive stimulus for all states (0 to 3) and inputs (0 to 1)
        for (s = 0; s < 4; s = s + 1) begin
            for (i = 0; i < 2; i = i + 1) begin
                state = s[1:0];
                in = i[0];
                #10;

                expected = get_expected(state, in);

                // 4-State Output Equality check using !==
                if (next_state !== expected[2:1] || out !== expected[0]) begin
                    errors = errors + 1;
                    $display("Mismatch: state=%b, in=%b | got next_state=%b, out=%b | expected next_state=%b, out=%b",
                             state, in, next_state, out, expected[2:1], expected[0]);
                end
            end
        end

        // Edge case / corner condition checks (e.g. unassigned or X/Z inputs if applicable)
        state = 2'bxx;
        in = 1'bx;
        #10;
        // Just verify it doesn't crash; we don't strictly assert exact outputs on X inputs
        // but we can check stability.

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

