        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    reg [99:0] expected;

    initial begin
        // Initialize inputs
        load = 0;
        ena = 2'b00;
        data = 100'h0;
        expected = 100'h0;

        @(posedge clk);
        #1;

        // Test 1: Load a specific test pattern
        load = 1'b1;
        ena = 2'b00;
        data = 100'h3F0F_0F0F_0F0F_0F0F_0F0F_0F0F_0001;
        expected = data;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Load failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 2: Rotate right by 1 bit (ena = 2'b01)
        // For right rotation: {q[0], q[99:1]}
        load = 1'b0;
        ena = 2'b01;
        expected = {expected[0], expected[99:1]};
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Rotate right failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 3: Rotate left by 1 bit (ena = 2'b10)
        // For left rotation: {q[98:0], q[99]}
        ena = 2'b10;
        expected = {expected[98:0], expected[99]};
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Rotate left failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 4: No rotation when ena = 2'b00
        ena = 2'b00;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: No rotation (00) changed state. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 5: No rotation when ena = 2'b11
        ena = 2'b11;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: No rotation (11) changed state. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 6: Load priority over enable
        load = 1'b1;
        ena = 2'b01;
        data = 100'hDEADBEEF_CAFE_BABE_1234_5678_9ABC_DEF0;
        expected = data;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Load priority failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

