    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // 3. Stimulus & self-checking
    integer errors = 0;
    reg [99:0] expected_q;

    initial begin
        // Initialize inputs
        load = 0;
        ena = 2'b00;
        data = 100'h0;
        expected_q = 100'h0;

        @(posedge clk);
        #1;

        // Test 1: Synchronous Load
        load = 1'b1;
        ena = 2'b00;
        data = 100'h123456789ABCDEF0123456789ABCDEF0;
        expected_q = data;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Load: expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 2: Disable load, hold state (ena = 2'b00)
        load = 1'b0;
        ena = 2'b00;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Hold (2'b00): expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 3: Hold state (ena = 2'b11)
        ena = 2'b11;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Hold (2'b11): expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 4: Rotate Right by 1 (ena = 2'b01)
        // Rotate right means q[0] goes to q[99], and everything else shifts right
        ena = 2'b01;
        expected_q = {expected_q[0], expected_q[99:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Rotate Right 1: expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 5: Rotate Right another time
        expected_q = {expected_q[0], expected_q[99:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Rotate Right 2: expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 6: Rotate Left by 1 (ena = 2'b10)
        // Rotate left means q[99] goes to q[0], and everything else shifts left
        ena = 2'b10;
        expected_q = {expected_q[98:0], expected_q[99]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Rotate Left 1: expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 7: Rotate Left another time
        expected_q = {expected_q[98:0], expected_q[99]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Rotate Left 2: expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Test 8: Load priority over enable
        load = 1'b1;
        ena = 2'b01; // rotate right requested, but load is active
        data = 100'hAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA;
        expected_q = data;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("Error on Load Priority: expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

