    reg clk;
    reg reset;
    reg in;
    wire out;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value using case inequality (`!==`)
    task check_output(input expected_out);
        begin
            @(posedge clk);
            #1; // small delay after clock edge for state update
            if (out !== expected_out) begin
                $display("Mismatch: time=%0t, in=%b, out=%b, expected_out=%b", $time, in, out, expected_out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        in = 0;

        // Test 1: Synchronous Reset Verification
        // Assert reset, verify state goes to B (out=1) regardless of 'in'
        reset = 1;
        in = 0;
        #10;
        if (out !== 1'b1) begin
            $display("Reset Mismatch: expected out=1 in state B, got out=%b", out);
            errors = errors + 1;
        end

        // Deassert reset
        @(negedge clk);
        reset = 0;

        // At this point, we are in state B (reset state, out=1).
        // Let's verify State B transitions:
        // B --in=1--> B (out=1)
        in = 1'b1;
        check_output(1'b1); // B -> B

        // B --in=0--> A (out=0)
        in = 1'b0;
        check_output(1'b0); // B -> A

        // Now we are in state A (out=0).
        // Let's verify State A transitions:
        // A --in=1--> A (out=0)
        in = 1'b1;
        check_output(1'b0); // A -> A

        // A --in=0--> B (out=1)
        in = 1'b0;
        check_output(1'b1); // A -> B

        // Additional thorough testing sequence
        // B --in=1--> B (out=1)
        in = 1'b1;
        check_output(1'b1);

        // B --in=0--> A (out=0)
        in = 1'b0;
        check_output(1'b0);

        // Test mid-sequence synchronous reset
        @(negedge clk);
        reset = 1;
        in = 1'b1; // trying to confuse with input while resetting
        #10;
        if (out !== 1'b1) begin
            $display("Mid-sequence Reset Mismatch: expected out=1, got out=%b", out);
