        #1;
        if (out !== 1'b1) begin
            $display("Post-reset release Mismatch: expected out=1, got out=%b", out);
            errors = errors + 1;
        end

        // Final result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

