    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value using case inequality (`!==`)
    task check_output;
        input expected_out;
        begin
            @(posedge clk);
            #1; // small delay after clock edge to sample stable output
            if (out !== expected_out) begin
                $display("Time %0t: Mismatch! in=%b, expected out=%b, got out=%b", $time, in, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        in = 0;

        // Test 1: Synchronous active-high reset check
        // Reset state should be B, which has out = 1.
        reset = 1;
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("Time %0t: Reset error! Expected out=1 in state B, got %b", $time, out);
            errors = errors + 1;
        end

        // Release reset
        reset = 0;

        // We are currently in state B (out=1)
        // Spec: B --in=1--> B (out=1)
        in = 1'b1;
        check_output(1'b1);

        // Spec: B --in=0--> A (out=0)
        in = 1'b0;
        check_output(1'b0);

        // We are now in state A (out=0)
        // Spec: A --in=1--> A (out=0)
        in = 1'b1;
        check_output(1'b0);

        // Spec: A --in=0--> B (out=1)
        in = 1'b0;
        check_output(1'b1);

        // Verify state persistence and edge transitions again
        // In B (out=1), in=1 -> B (out=1)
        in = 1'b1;
        check_output(1'b1);

        // In B (out=1), in=0 -> A (out=0)
        in = 1'b0;
        check_output(1'b0);

        // Test mid-sequence synchronous reset assertion
        reset = 1;
        in = 1'b1; // even with in=1, reset should force state B (out=1)
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("Time %0t: Synchronous reset during operation failed! Expected out=1, got %b", $time, out);
            errors = errors + 1;
        end

        reset = 0;
        check_output(1'b1); // in state B, in=1 keeps us in B (out=1)

        // Final evaluation
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

