`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    reg in;
    wire out;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Clock generation
    always #5 clk = ~clk;

    integer errors = 0;

    initial begin
        clk = 0;
        reset = 0;
        in = 0;

        // Test 1: Active-high synchronous/asynchronous reset check
        // The prompt says: "reset is active-high synchronous" but RTL has `posedge reset` in sensitivity list.
        // Let's test reset behavior.
        reset = 1;
        in = 0;
        #10;
        if (out !== 1) begin
            $display("ERROR: Reset failed to set out=1. Got %b", out);
            errors = errors + 1;
        end

        // Release reset synchronously/asynchronously
        @(posedge clk);
        reset = 0;
        #1;
        if (out !== 1) begin
            $display("ERROR: Out changed immediately after reset release. Got %b", out);
            errors = errors + 1;
        end

        // State B: out=1
        // B --in=0--> A
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 0) begin
            $display("ERROR: Transition B->A on in=0 failed. Expected out=0, got %b", out);
            errors = errors + 1;
        end

        // State A: out=0
        // A --in=1--> A
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 0) begin
            $display("ERROR: Transition A->A on in=1 failed. Expected out=0, got %b", out);
            errors = errors + 1;
        end

        // State A: out=0
        // A --in=0--> B
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 1) begin
            $display("ERROR: Transition A->B on in=0 failed. Expected out=1, got %b", out);
            errors = errors + 1;
        end

        // State B: out=1
        // B --in=1--> B
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1) begin
            $display("ERROR: Transition B->B on in=1 failed. Expected out=1, got %b", out);
            errors = errors + 1;
        end

        // Additional Adversarial Check: Look for non-blocking vs blocking assignments to 'out'.
        // In the candidate RTL, 'out' is assigned combinationally in the always @(*) block,
        // but also assigned via non-blocking assignment (`out <= 1`) on `posedge reset`.
        // This is a classic multiple-driver / mixed assignment bug in Verilog/SystemVerilog!
        // Let's assert reset again while clk is low to see if it causes race conditions or multiple drivers.
        @(negedge clk);
        reset = 1;
        #2;
        if (out !== 1) begin
            $display("ERROR: Reset assertion race condition detected. out = %b", out);
            errors = errors + 1;
        end

        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

