        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value
    task check_output(input expected_out);
        begin
            @(posedge clk);
            #1; // Small delay to allow combinational/sequential update after clock edge
            if (out !== expected_out) begin
                $display("Mismatch at time %0t: in=%b, expected out=%b, got out=%b", 
                         $time, in, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        in = 0;

        // Apply synchronous reset for a few cycles
        #12;
        // Specification: Reset state is B, where out = 1
        if (out !== 1'b1) begin
            $display("Reset check failed: expected out=1 in state B, got out=%b", out);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Test state transitions from State B (out=1)
        // Transition: B --in=1--> B (out=1)
        in = 1'b1;
        check_output(1'b1);

        // Transition: B --in=0--> A (out=0)
        in = 1'b0;
        check_output(1'b0);

        // Test state transitions from State A (out=0)
        // Transition: A --in=0--> B (out=1)
        in = 1'b0;
        check_output(1'b1);

        // Now we are back in State B (out=1)
        // Transition: B --in=0--> A (out=0)
        in = 1'b0;
        check_output(1'b0);

        // Transition: A --in=1--> A (out=0)
        in = 1'b1;
        check_output(1'b0);

        // Transition: A --in=1--> A (out=0)
        in = 1'b1;
        check_output(1'b0);

        // Test synchronous reset while running
        @(posedge clk);
        reset = 1;
        #1;
        if (out !== 1'b1) begin
            $display("Mid-run reset check failed: expected out=1, got out=%b", out);
            errors = errors + 1;
        end

        // Final report
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

