        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        in = 0;

        // Test 1: Asynchronous reset test
        // Assert reset asynchronously
        #2;
        areset = 1;
        #3;
        // At this point, even without clock edge, areset should force state to B (out = 1)
        if (out !== 1'b1) begin
            errors = errors + 1;
        end

        // Deassert reset
        #5;
        areset = 0;
        #1;
        // Verify output is still 1 (State B)
