`timescale 1ns/1ps

module tb;
    reg clk;
    reg areset;
    reg in;
    wire out;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value
    task check_output(input expected_out);
        begin
            // Wait for rising edge/settling
            #1;
            if (out !== expected_out) begin
                $display("Time %0t: Mismatch! in=%b, expected out=%b, got out=%b", 
                         $time, in, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        clk = 0;
        areset = 0;
        in = 0;

        // 1. Test asynchronous reset behavior
        // Reset goes high asynchronously
        areset = 1;
        #2;
        // Spec says: "asynchronously reset into state B if reset if high"
        // State B output is 1 according to the diagram: B (1)
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset fail! Expected out=1 for state B, got %b", $time, out);
            errors = errors + 1;
        end

        // Release reset
        areset = 0;
        #3;
        // Verify state B persists immediately after reset release
        check_output(1'b1); // State B

        // 2. Test transitions from State B (out = 1)
        // Diagram:
        // B (1) --0--> A (0)
        // B (1) --1--> B (1)

        @(posedge clk);
        in = 1'b1; // B --1--> B
        check_output(1'b1);

        @(posedge clk);
        in = 1'b0; // B --0--> A
        check_output(1'b0); // State A output is 0

        // 3. Test transitions from State A (out = 0)
        // Diagram:
        // A (0) --0--> B (1)
        // A (0) --1--> A (0)

        @(posedge clk);
        in = 1'b1; // A --1--> A
        check_output(1'b0);

        @(posedge clk);
        in = 1'b0; // A --0--> B
        check_output(1'b1);

        // 4. Test asynchronous reset override during operation
        @(posedge clk);
        in = 1'b0; // currently in B, 0 goes to A
        #1;
        areset = 1; // Assert reset asynchronously
        #1;
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset during operation fail! Expected out=1, got %b", $time, out);
            errors = errors + 1;
        end
        areset = 0;
        #3;

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

