    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value using case inequality (!==)
    task check_output(input expected_out);
        begin
            #1; // Small delay to let combinational/sequential logic settle after clock edge
            if (out !== expected_out) begin
                $display("Time %0t: Mismatch! in=%b, out=%b (expected %b)", $time, in, out, expected_out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        in = 0;

        // Test 1: Asynchronous Reset Test
        // Assert areset high, check that it resets to state B (out = 1 based on spec: B=1, A=0)
        areset = 1;
        in = 0;
        #12;
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset failed! out=%b (expected 1)", $time, out);
            errors = errors + 1;
        end

        // Release reset
        areset = 0;
        #5;

        // Spec analysis:
        // State B (out = 1): --0--> State A, --1--> State B
        // State A (out = 0): --0--> State B, --1--> State A

        // Currently in State B (from reset, out = 1).
        // Let's test transitions from State B:
        // Transition: B --1--> B (out should remain 1)
        in = 1'b1;
        @(posedge clk);
        check_output(1'b1); // Should be in B (out=1)

        // Transition: B --0--> A (out should become 0)
        in = 1'b0;
        @(posedge clk);
        check_output(1'b0); // Should be in A (out=0)

        // Now we are in State A (out = 0).
        // Let's test transitions from State A:
        // Transition: A --1--> A (out should remain 0)
        in = 1'b1;
        @(posedge clk);
        check_output(1'b0); // Should be in A (out=0)

        // Transition: A --0--> B (out should become 1)
        in = 1'b0;
        @(posedge clk);
        check_output(1'b1); // Should be in B (out=1)

        // Test asynchronous reset recovery again during operation
        in = 1'b0; // from B with in=0 goes to A
