        #2;
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset mid-operation failed! out=%b (expected 1)", $time, out);
            errors = errors + 1;
        end

        areset = 0;
        #3;
        check_output(1'b1); // Should remain in B after reset release

        // Final evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

