module TopModule (
    input  clk,
    input  areset,
    input  j,
    input  k,
    output reg out
);

    // State encoding
    typedef enum reg [1:0] {
        OFF = 2'b00,
        ON  = 2'b01
    } state_t;

    state_t current_state, next_state;

    // Asynchronous reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= OFF;
            out <= 0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            OFF: begin
                if (j) begin
                    next_state = ON;
                    out = 1;
                end else begin
                    next_state = OFF;
                    out = 0;
                end
            end
            ON: begin
                if (k) begin
                    next_state = OFF;
                    out = 0;
                end else begin
                    next_state = ON;
                    out = 1;
                end
            end
            default: begin
                next_state = OFF;
                out = 0;
            end
        endcase
    end

endmodule

