        // Stay in ON state
        j = 0; k = 0; // Set j to 0, k to 0
        #10; // Wait for clock
        if (out !== 1) errors = errors + 1; // Check output remains ON

        // Transition to OFF state
        k = 1; // Set k to 1
        #10; // Wait for clock
        if (out !== 0) errors = errors + 1; // Check output in OFF state

        // Stay in OFF state
        j = 0; k = 0; // Set j to 0, k to 0
        #10; // Wait for clock
        if (out !== 0) errors = errors + 1; // Check output remains OFF

        // Transition to ON state again
        j = 1; k = 0; // Set j to 1
        #10; // Wait for clock
        if (out !== 1) errors = errors + 1; // Check output in ON state

        // Transition to OFF state again
        k = 1; // Set k to 1
        #10; // Wait for clock
        if (out !== 0) errors = errors + 1; // Check output in OFF state

        // Final check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
