`timescale 1ns/1ps

module tb;
    reg clk;
    reg areset;
    reg j;
    reg k;
    wire out;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .j(j),
        .k(k),
        .out(out)
    );

    // Clock generation
    always #5 clk = ~clk;

    integer errors = 0;

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        j = 0;
        k = 0;

        // 1. Test Asynchronous Reset (Corner Case: active high async reset)
        #2;
        areset = 1;
        #3;
        if (out !== 1'b0) begin
            $display("ERROR: Async reset failed to set out to 0 immediately. Got %b", out);
            errors = errors + 1;
        end
        #5;
        areset = 0; // Deassert reset

        // State should be OFF, out = 0
        #2;
        if (out !== 1'b0) begin
            $display("ERROR: State after reset deassertion should be OFF (out=0). Got %b", out);
            errors = errors + 1;
        end

        // 2. Test OFF state with j=0 -> should stay OFF (out=0)
        @(posedge clk);
        j = 0; k = 0;
        #2;
        if (out !== 1'b0) begin
            $display("ERROR: OFF + j=0 should remain OFF (out=0). Got %b", out);
            errors = errors + 1;
        end

        // 3. Test OFF state with j=1 -> should transition to ON (out=1)
        @(posedge clk);
        j = 1; k = 0;
        #2;
        if (out !== 1'b1) begin
            $display("ERROR: OFF + j=1 should transition to ON (out=1). Got %b", out);
            errors = errors + 1;
        end

        // 4. Test ON state with k=0 -> should stay ON (out=1)
        @(posedge clk);
        j = 0; k = 0;
        #2;
        if (out !== 1'b1) begin
            $display("ERROR: ON + k=0 should remain ON (out=1). Got %b", out);
            errors = errors + 1;
        end

        // 5. Test ON state with k=1 -> should transition to OFF (out=0)
        @(posedge clk);
        j = 0; k = 1;
        #2;
        if (out !== 1'b0) begin
            $display("ERROR: ON + k=1 should transition to OFF (out=0). Got %b", out);
            errors = errors + 1;
        end

        // 6. Test asynchronous reset assertion while in ON state / mid-cycle
        @(posedge clk);
        j = 1; k = 0; // Go to ON
        #2;
        areset = 1; // Assert reset asynchronously
        #1;
        if (out !== 1'b0) begin
            $display("ERROR: Async reset during operation failed. Got %b", out);
            errors = errors + 1;
        end
        #4;
        areset = 0;
        #2;
        if (out !== 1'b0) begin
            $display("ERROR: Post-reset state incorrect. Got %b", out);
            errors = errors + 1;
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

