        .clk(clk),
        .areset(areset),
        .j(j),
        .k(k),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        j = 0;
        k = 0;

        // Test 1: Asynchronous Reset Test
        // Assert reset asynchronously and check state immediately (should be OFF, out = 0)
        areset = 1;
        #3;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        #7;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Test 2: State OFF transitions
        // In OFF state (out=0), j=0 should keep it in OFF (out=0)
        @(posedge clk);
        j = 0; k = 0;
        #2;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // In OFF state (out=0), j=1 should transition to ON (out=1) on clock edge
        @(posedge clk);
        j = 1; k = 0;
        #2;
        if (out !== 1'b1) begin
            errors = errors + 1;
        end

        // Test 3: State ON transitions
        // In ON state (out=1), k=0 should keep it in ON (out=1)
        @(posedge clk);
        j = 0; k = 0;
        #2;
        if (out !== 1'b1) begin
            errors = errors + 1;
        end

        // In ON state (out=1), k=1 should transition to OFF (out=0) on clock edge
        @(posedge clk);
        j = 0; k = 1;
        #2;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Test 4: Priority / Edge Cases (e.g., both j and k active, or asynchronous reset during operation)
        // Go to ON
        @(posedge clk);
        j = 1; k = 0;
        #2;
        if (out !== 1'b1) begin
            errors = errors + 1;
        end

        // Active asynchronous reset check mid-operation
        areset = 1;
        #3;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end
        areset = 0;
        #7;

        // Final evaluation check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

