            errors = errors + 1;
        end

        // Test 2: OFF state with j=0 -> should stay OFF
        @(posedge clk);
        j = 0;
        k = 0;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Test 3: OFF state with j=1 -> should transition to ON
        // Note: Due to synchronous state update, output updates on the clock edge
        // based on current_state == ON. Let's check transition timing.
