    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check expected output
    task check_output(input expected_out);
        begin
            #1; // Small delay to allow combinational/sequential update
            if (out !== expected_out) begin
                $display("Time %0t: Mismatch! j=%b, k=%b, reset=%b | Expected out=%b, Got out=%b", 
                         $time, j, k, reset, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        j = 0;
        k = 0;

        // Apply synchronous active-high reset
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        check_output(1'b0); // OFF state, out should be 0

        // Release reset
        reset = 0;
        @(posedge clk);
        check_output(1'b0); // Should remain OFF (out=0)

        // Test 1: OFF state, j=0 -> should stay OFF (out=0)
        j = 0; k = 0;
        @(posedge clk);
        check_output(1'b0);

        // Test 2: OFF state, j=1 -> should transition to ON (out=1)
        j = 1; k = 0;
        @(posedge clk);
        check_output(1'b1);

        // Test 3: ON state, k=0 -> should stay ON (out=1)
        j = 0; k = 0;
        @(posedge clk);
        check_output(1'b1);

        // Test 4: ON state, k=1 -> should transition to OFF (out=0)
        j = 0; k = 1;
        @(posedge clk);
        check_output(1'b0);

        // Test 5: Priority / simultaneous j and k check (specification dependent, 
