    always #5 clk = ~clk;

    integer errors = 0;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        j = 0;
        k = 0;

        // Apply synchronous/asynchronous reset check
        #12;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        #10;

        // Test 1: OFF state, j=0 -> should stay OFF (out=0)
        j = 1'b0;
        k = 1'b0;
        #10;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Test 2: OFF state, j=1 -> should transition to ON (out=1)
        j = 1'b1;
        #10;
        if (out !== 1'b1) begin
            errors = errors + 1;
        end

        // Test 3: ON state, k=0 -> should stay ON (out=1)
        j = 1'b0;
        k = 1'b0;
        #10;
        if (out !== 1'b1) begin
            errors = errors + 1;
        end

        // Test 4: ON state, k=1 -> should transition to OFF (out=0)
        k = 1'b1;
        #10;
        if (out !== 1'b0) begin
            errors = errors + 1;
        end

        // Test 5: Priority / simultaneous j=1 and k=1 while OFF
        // If OFF, j=1 should take us to ON regardless of k (or check spec behavior)
        reset = 1;
        #10;
        reset = 0;
        #10;
