        #5;
        reset = 0;
        #10;
        if (out !== 1'b0) errors = errors + 1;

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

