`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    reg j;
    reg k;
    wire out;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .j(j),
        .k(k),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check expected output
    task check_output(input expected);
        begin
            #1; // Allow combinational/sequential settling
            if (out !== expected) begin
                $display("Time %0t: Mismatch! j=%b, k=%b, reset=%b | Expected out=%b, Got out=%b", 
                         $time, j, k, reset, expected, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        j = 0;
        k = 0;

        // Apply Reset
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        check_output(1'b0); // OFF state -> out = 0

        // Release Reset
        reset = 0;
        @(posedge clk);

        // Test State: OFF (out=0) --j=0--> OFF
        j = 0;
        k = 0;
        @(posedge clk);
        check_output(1'b0);

        // Test State: OFF (out=0) --j=1--> ON
        j = 1;
        k = 0;
        @(posedge clk);
        check_output(1'b1); // Should transition to ON, out = 1

        // Test State: ON (out=1) --k=0--> ON
        j = 0;
        k = 0;
        @(posedge clk);
        check_output(1'b1); // Should stay ON, out = 1

        // Test State: ON (out=1) --k=1--> OFF
        j = 0;
        k = 1;
        @(posedge clk);
        check_output(1'b0); // Should transition to OFF, out = 0

        // Test synchronous reset while in OFF state
        j = 1; // normally goes to ON
        @(posedge clk); // moves to ON
        check_output(1'b1);

        reset = 1; // active-high sync reset
        @(posedge clk);
        check_output(1'b0); // Should force back to OFF

        reset = 0;
        @(posedge clk);
        check_output(1'b0);

        // Final Result Report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

