`timescale 1ns/1ps

module tb;
    reg  [7:0] code;
    wire [3:0] out;
    wire       valid;

    integer errors = 0;
    integer i;

    // Instantiate DUT strictly using 'TopModule dut'
    TopModule dut (
        .code  (code),
        .out   (out),
        .valid (valid)
    );

    // Expected value helper task
    task check_case(input [7:0] test_code, input [3:0] exp_out, input exp_valid);
        begin
            code = test_code;
            #10;
            if ((out !== exp_out) || (valid !== exp_valid)) begin
                $display("Mismatch: code = 0x%h | got out = 0x%h, valid = %b | expected out = 0x%h, valid = %b", 
                         test_code, out, valid, exp_out, exp_valid);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // 1. Test all 10 valid scancodes
        check_case(8'h45, 4'd0, 1'b1);
        check_case(8'h16, 4'd1, 1'b1);
        check_case(8'h1e, 4'd2, 1'b1);
        check_case(8'h26, 4'd3, 1'b1);
        check_case(8'h25, 4'd4, 1'b1);
        check_case(8'h2e, 4'd5, 1'b1);
        check_case(8'h36, 4'd6, 1'b1);
        check_case(8'h3d, 4'd7, 1'b1);
        check_case(8'h3e, 4'd8, 1'b1);
        check_case(8'h46, 4'd9, 1'b1);

        // 2. Test boundary / random invalid scancodes
        check_case(8'h00, 4'd0, 1'b0);
        check_case(8'hFF, 4'd0, 1'b0);
        check_case(8'h44, 4'd0, 1'b0); // Near 8'h45
        check_case(8'h47, 4'd0, 1'b0); // Near 8'h46
        check_case(8'h15, 4'd0, 1'b0); // Near 8'h16
        check_case(8'h17, 4'd0, 1'b0); // Near 8'h16

        // 3. Bounded loop over a wider set of invalid codes to check for latches or unexpected behaviors
        for (i = 0; i < 256; i = i + 1) begin
            if (i != 8'h45 && i != 8'h16 && i != 8'h1e && i != 8'h26 && 
                i != 8'h25 && i != 8'h2e && i != 8'h36 && i != 8'h3d && 
                i != 8'h3e && i != 8'h46) begin
                check_case(i[7:0], 4'd0, 1'b0);
            end
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

