test_code:
`timescale 1ns/1ps

module tb;
    reg clk;
    reg load;
    reg ena;
    reg [1:0] amount;
    reg [63:0] data;
    wire [63:0] q;

    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .amount(amount),
        .data(data),
        .q(q)
    );

    always #5 clk = ~clk;

    integer errors = 0;
    reg [63:0] expected;

    initial begin
        clk = 0;
        load = 0;
        ena = 0;
        amount = 2'b00;
        data = 64'h0;
        #12;

        // Test 1: Synchronous Load
        @(posedge clk);
        load = 1;
        ena = 0;
        data = 64'h8000000000000001; // Negative sign bit set (MSB = 1)
        #10;
        expected = 64'h8000000000000001;
        if (q !== expected) begin
            $display("FAIL: Load test failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 2: Shift Left by 1 (amount = 2'b00)
        @(posedge clk);
        load = 0;
        ena = 1;
        amount = 2'b00;
        #10;
        expected = 64'h0000000000000002;
        if (q !== expected) begin
            $display("FAIL: Shift left 1 failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 3: Shift Left by 8 (amount = 2'b01)
        // Current q should be 0x02, shifting left by 8 -> 0x200
        @(posedge clk);
        amount = 2'b01;
        #10;
        expected = 64'h0000000000000200;
        if (q !== expected) begin
            $display("FAIL: Shift left 8 failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 4: Load a negative number for arithmetic right shift testing
        @(posedge clk);
        load = 1;
        data = 64'hFF00FF00FF00FF00;
        #10;

        // Test 5: Arithmetic Right Shift by 1 (amount = 2'b10)
        // MSB is 1 (0xFF...), should sign-extend
        @(posedge clk);
        load = 0;
        ena = 1;
        amount = 2'b10;
        #10;
        expected = {1'b1, 64'hFF00FF00FF00FF00 >> 1}; 
        // Wait, let's verify exact bits: {q[63], q[63:1]} => {1'b1, 64'hFF807F807F807F80}
        // Let's compute expected precisely:
        // q was FF00FF00FF00FF00. MSB is 1. q[63:1] is FF807F807F807F8. 
        // Concatenating {1'b1, FF807F807F807F8} -> FF807F807F807F80.
        expected = 64'hFF807F807F807F80;
        if (q !== expected) begin
            $display("FAIL: Arithmetic right shift 1 failed. Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Test 6: Arithmetic Right Shift by 8 (amount = 2'b11)
        // Let's inspect candidate RTL for amount=2'b11:
        // 2'b11: q <= {q[63], q[63:8]};
        // BUG EXPOSURE: {q[63], q[63:8]} results in a 1 + 56 = 57-bit vector padded/truncated incorrectly!
        // A 64-bit assignment from a 57-bit concatenation will zero-extend or misalign the upper bits!
        // Let's run this test to expose the concatenation bug in the RTL.
        @(posedge clk);
        amount = 2'b11;
        #10;
        // If RTL has {q[63], q[63:8]}, output width mismatch / wrong shift occurs.
        // Correct arithmetic right shift by 8 should replicate sign bit 8 times: {8{q[63]}, q[63:8]}
        // Let's see what the candidate actually produces and check if it matches standard arithmetic shift.
        // Expected correct arithmetic shift by 8 of previous q (FF807F807F807F80):
        // Should be FF00F807F807F807... let's check: 8'hFF, then q[63:8]
        // q[63:8] of FF807F807F807F80 is FF807F807F807F
        // Correct expected: 64'hFFFF807F807F807F
        // But candidate does: {q[63], q[63:8]} -> 1 bit of sign + 56 bits = 57 bits, assigned to 64-bit reg (zero padded on MSBs!)
        // This will definitively trigger a failure!

        expected = 64'hFFFF807F807F807F;
        if (q !== expected) begin
            $display("FAIL: Arithmetic right shift 8 failed / bug exposed! Expected %h, got %h", expected, q);
            errors = errors + 1;
        end

        // Finish up
        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

