design_code:
module TopModule (
    input  [7:0] a,
    input  [7:0] b,
    output [7:0] s,
    output       overflow
);

    // Perform the 8-bit addition
    assign s = a + b;

    // Signed overflow occurs when:
    // - Two positive numbers (a[7]=0, b[7]=0) add up to a negative result (s[7]=1)
    // - Two negative numbers (a[7]=1, b[7]=1) add up to a positive result (s[7]=0)
    assign overflow = (~a[7] & ~b[7] & s[7]) | (a[7] & b[7] & ~s[7]);

endmodule

test_code:
`timescale 1ns/1ps

module tb;

    // 1. Declare inputs as regs, outputs as wires
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;
    integer i, j;
    reg [8:0] expected_full;
    reg       expected_overflow;
    reg [7:0] expected_s;

    initial begin
        // Initialize inputs
        a = 8'h00;
        b = 8'h00;
        #10;

        // Apply a concise set of meaningful test vectors covering:
        // - Positive + Positive (no overflow)
        // - Positive + Positive (overflow)
        // - Negative + Negative (no overflow)
        // - Negative + Negative (overflow)
        // - Positive + Negative (never overflows)
        // - Zero values and corner cases

        // Test vector array: {a, b}
        // Let's test specific interesting cases and a bounded loop

        // Specific targeted vectors
        apply_test(8'h01, 8'h01); // 1 + 1 = 2
        apply_test(8'h7F, 8'h01); // 127 + 1 = 128 (Overflow: max positive + 1)
        apply_test(8'h7F, 8'h7F); // 127 + 127 = 254 -> -2 (Overflow)
        apply_test(8'h80, 8'h80); // -128 + -128 = -256 -> 0 (Overflow: max negative + max negative)
        apply_test(8'h81, 8'hFF); // -127 + -1 = -128 (No overflow)
        apply_test(8'h50, 8'h30); // 80 + 48 = 128 (Overflow)
        apply_test(8'h50, 8'hB0); // 80 + (-80) = 0 (No overflow)
        apply_test(8'h00, 8'h00); // 0 + 0 = 0
        apply_test(8'hFF, 8'h01); // -1 + 1 = 0

        // Bounded loop for additional verification (e.g., small step combinations)
        for (i = 0; i < 256; i = i + 32) begin
            for (j = 0; j < 256; j = j + 32) begin
                apply_test(i[7:0], j[7:0]);
            end
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    // Task to apply stimulus and check against golden model using 4-state case inequality
    task apply_test(input [7:0] test_a, input [7:0] test_b);
        begin
            a = test_a;
            b = test_b;
            #5; // Wait for combinational propagation

            // Compute expected values using 9-bit arithmetic for signed overflow check
            // Signed addition overflow occurs when the carry into the sign bit 
            // differs from the carry out, or simply by checking operand signs vs result sign.
            expected_full = $signed(test_a) + $signed(test_b);
            expected_s    = expected_full[7:0];

            // Overflow condition for 2's complement 8-bit addition:
            expected_overflow = (~test_a[7] & ~test_b[7] & expected_s[7]) | 
                                ( test_a[7] &  test_b[7] & ~expected_s[7]);

            // Assertions using !== (4-state inequality requirement)
            if (s !== expected_s || overflow !== expected_overflow) begin
                $display("ERROR: a=%h (%0d), b=%h (%0d) | Expected s=%h, overflow=%b | Got s=%h, overflow=%b", 
                         test_a, $signed(test_a), test_b, $signed(test_b), 
                         expected_s, expected_overflow, s, overflow);
                errors = errors + 1;
            end
            #5;
        end
    endtask

endmodule

