    a = 8'b01111111; b = 8'b00000001; #10; // 127 + 1 = -128, overflow
    if (s !== 8'b10000000 || overflow !== 1'b1) $display("*** TEST RESULT: FAIL ***");

    a = 8'b11111111; b = 8'b00000001; #10; // -1 + 1 = 0, no overflow
    if (s !== 8'b00000000 || overflow !== 1'b0) $display("*** TEST RESULT: FAIL ***");

    a = 8'b01111111; b = 8'b01111111; #10; // 127 + 127 = 254, no overflow
    if (s !== 8'b11111110 || overflow !== 1'b0) $display("*** TEST RESULT: FAIL ***");

    a = 8'b10000000; b = 8'b10000000; #10; // -128 + -128 = 0, no overflow
    if (s !== 8'b00000000 || overflow !== 1'b0) $display("*** TEST RESULT: FAIL ***");

    a = 8'b10000001; b = 8'b01111111; #10; // -127 + 127 = 0, no overflow
    if (s !== 8'b00000000 || overflow !== 1'b0) $display("*** TEST RESULT: FAIL ***");

    a = 8'b01111111; b = 8'b01111111; #10; // 127 + 127 = 254, no overflow
    if (s !== 8'b11111110 || overflow !== 1'b0) $display("*** TEST RESULT: FAIL ***");

    // Final check
    $display("*** TEST RESULT: PASS ***");
    $finish;
  end
