`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    // Instantiate TopModule dut
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;

    // Task to check results
    task check_result;
        input [7:0] exp_s;
        input       exp_ovf;
        begin
            #1; // Allow combinational propagation
            if ((s !== exp_s) || (overflow !== exp_ovf)) begin
                $display("ERROR: a = %d (%b), b = %d (%b) | Got s = %d (%b), overflow = %b | Expected s = %d (%b), overflow = %b", 
                         $signed(a), a, $signed(b), b, $signed(s), s, overflow, $signed(exp_s), exp_s, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Test Vector 1: Zero + Zero
        a = 8'd0; b = 8'd0;
        check_result(8'd0, 1'b0);

        // Test Vector 2: Positive + Positive (No overflow)
        a = 8'd10; b = 8'd20;
        check_result(8'd30, 1'b0);

        // Test Vector 3: Positive + Positive (Overflow)
        // 100 + 50 = 150 -> -106 in 8-bit signed
        a = 8'd100; b = 8'd50;
        check_result(8'd150, 1'b1);

        // Test Vector 4: Negative + Negative (No overflow)
        a = -8'd10; b = -8'd20;
        check_result(-8'd30, 1'b0);

        // Test Vector 5: Negative + Negative (Overflow)
        // -100 + (-50) = -150 -> 106 in 8-bit signed
        a = -8'd100; b = -8'd50;
        check_result(-8'd150, 1'b1);

        // Test Vector 6: Positive + Negative (Never overflows)
        a = 8'd50; b = -8'd20;
        check_result(8'd30, 1'b0);

        // Test Vector 7: Negative + Positive (Never overflows)
        a = -8'd50; b = 8'd20;
        check_result(-8'd30, 1'b0);

        // Test Vector 8: Max Positive + 1 (Overflow)
        a = 8'h7F; b = 8'h01; // 127 + 1 = 128 (-128)
        check_result(8'h80, 1'b1);

        // Test Vector 9: Max Negative + (-1) (Overflow)
        a = 8'h80; b = 8'hFF; // -128 + (-1) = -129 (127)
        check_result(8'h7F, 1'b1);

        // Bounded loop for randomized/exhaustive-like spot checks
        repeat (10) begin
            a = $random;
            b = $random;
            // Calculate expected using standard Verilog signed math
            begin
                reg signed [8:0] sum_full;
                reg              exp_ovf;
                reg [7:0]        exp_s;

                sum_full = $signed(a) + $signed(b);
                exp_s = sum_full[7:0];
                exp_ovf = ((~a[7] & ~b[7] & exp_s[7]) | (a[7] & b[7] & ~exp_s[7]));

                check_result(exp_s, exp_ovf);
            end
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

