        if (q !== 4'd1) begin
            $display("Error at reset: expected 4'd1, got %d", q);
            errors = errors + 1;
        end

        // Release reset
        reset = 0;

        // Check counting sequence 1 through 10, then wrapping back to 1
        // We will run through two full cycles (1 to 10 twice) to ensure proper rollover
