module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg a;
    reg b;
    reg c;
    reg d;
    reg e;
    wire [24:0] out;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .e(e),
        .out(out)
    );

    integer errors = 0;
    integer i, j;
    reg [4:0] inputs;
    reg [4:0] in_arr [4:0];
    reg [24:0] expected;

    initial begin
        // Initialize inputs
        a = 0;
        b = 0;
        c = 0;
        d = 0;
        e = 0;
        #10;

        // Test all 32 possible combinations of 5-bit inputs (a, b, c, d, e)
        for (i = 0; i < 32; i = i + 1) begin
            {a, b, c, d, e} = i[4:0];
            #10;

            // Compute expected output bit by bit
            // out[(4 - row) * 5 + (4 - col)] = ~(in[4 - row] ^ in[4 - col])
            in_arr[0] = a;
            in_arr[1] = b;
            in_arr[2] = c;
            in_arr[3] = d;
            in_arr[4] = e;

            for (j = 0; j < 25; j = j + 1) begin
                // j maps to (4 - row) * 5 + (4 - col)
                // Let's extract row and col from j
                // row_idx = 4 - (j / 5);
                // col_idx = 4 - (j % 5);
                // Actually, the RTL formula is: index = (4 - i_loop) * 5 + (4 - j_loop)
                // So:
                // i_loop = 4 - (j / 5);
                // j_loop = 4 - (j % 5);
                // expected[j] = ~(in_arr[i_loop] ^ in_arr[j_loop]);

                // Let's use the exact loop structure to build expected
                // indices:
                // index = (4 - r) * 5 + (4 - c_val)
            end

            // Re-evaluating expected cleanly:
            begin
                integer r, c_val;
                for (r = 0; r < 5; r = r + 1) begin
                    for (c_val = 0; c_val < 5; c_val = c_val + 1) begin
                        integer idx;
                        idx = (4 - r) * 5 + (4 - c_val);
                        expected[idx] = ~(in_arr[r] ^ in_arr[c_val]);
                    end
                end
            end

            // 4-State Output Equality Check using !==
            if (out !== expected) begin
                $display("Mismatch at inputs a=%b b=%b c=%b d=%b e=%b: expected %b, got %b",
                         a, b, c, d, e, expected, out);
                errors = errors + 1;
            end
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

