module TopModule (
    input        clk,
    input        reset,
    output [3:0] ena,
    output [15:0] q
);

    // Internal registers for the 4 BCD digits
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // Enable signals generation
    // ena[0]: ones digit enable (always 1)
    // ena[1]: tens digit enable (when ones reaches 9)
    // ena[2]: hundreds digit enable (when tens and ones reach 9)
    // ena[3]: thousands digit enable (when hundreds, tens, and ones reach 9)
    assign ena[0] = 1'b1;
    assign ena[1] = (ones == 4'd9);
    assign ena[2] = (ones == 4'd9) && (tens == 4'd9);
    assign ena[3] = (ones == 4'd9) && (tens == 4'd9) && (hundreds == 4'd9);

    // Sequential logic for BCD counter
    always @(posedge clk) begin
        if (reset) begin
            ones      <= 4'd0;
            tens      <= 4'd0;
            hundreds  <= 4'd0;
            thousands <= 4'd0;
        end else begin
            // Ones digit
            if (ones == 4'd9) begin
                ones <= 4'd0;

                // Tens digit
                if (tens == 4'd9) begin
                    tens <= 4'd0;

                    // Hundreds digit
                    if (hundreds == 4'd9) begin
                        hundreds <= 4'd0;

                        // Thousands digit
                        if (thousands == 4'd9) begin
                            thousands <= 4'd0;
                        end else begin
                            thousands <= thousands + 4'd1;
                        end

                    end else begin
                        hundreds <= hundreds + 4'd1;
                    end

                end else begin
                    tens <= tens + 4'd1;
                end

            end else begin
                ones <= ones + 4'd1;
            end
        end
    end

    // Assign to output q
    // q[3:0]   : ones
    // q[7:4]   : tens
    // q[11:8]  : hundreds
    // q[15:12] : thousands
    assign q = {thousands, hundreds, tens, ones};

endmodule

