`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        reset;
    wire [3:0] ena;
    wire [15:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Error counter
    integer errors = 0;

    // Expected values for checking
    reg [3:0] exp_ones;
    reg [3:0] exp_tens;
    reg [3:0] exp_hundreds;
    reg [3:0] exp_thousands;
    reg [3:0] exp_ena;
    reg [15:0] exp_q;

    // Task to calculate expected BCD counter values for validation
    function [15:0] calc_next_q;
        input [15:0] current_q;
        reg [3:0] o, t, h, th;
        reg e1, e2, e3;
        begin
            o  = current_q[3:0];
            t  = current_q[7:4];
            h  = current_q[11:8];
            th = current_q[15:12];

            e1 = (o == 4'd9);
            e2 = e1 && (t == 4'd9);
            e3 = e2 && (h == 4'd9);

            // Update ones
            if (o == 4'd9) o = 4'd0;
            else           o = o + 4'd1;

            // Update tens
            if (e1) begin
                if (t == 4'd9) t = 4'd0;
                else           t = t + 4'd1;
            end

            // Update hundreds
            if (e2) begin
                if (h == 4'd9) h = 4'd0;
                else           h = h + 4'd1;
            end

            // Update thousands
            if (e3) begin
                if (th == 4'd9) th = 4'd0;
                else            th = th + 4'd1;
            end

            calc_next_q = {th, h, t, o};
        end
    endfunction

    function [3:0] calc_ena;
        input [15:0] current_q;
        reg [3:0] o, t, h, th;
        reg e1, e2, e3;
        begin
            o  = current_q[3:0];
            t  = current_q[7:4];
            h  = current_q[11:8];
            th = current_q[15:12];

            e1 = (o == 4'd9);
            e2 = e1 && (t == 4'd9);
            e3 = e2 && (h == 4'd9);

            calc_ena = {e3, e2, e1, 1'b1};
        end
    endfunction

    integer i;
    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;

        // Apply reset
        #12;
        reset = 0;

        // Check reset state
        exp_q = 16'h0000;
        exp_ena = 4'b0001;

        if (q !== exp_q) begin
            errors = errors + 1;
        end
        if (ena !== exp_ena) begin
            errors = errors + 1;
        end

        // Run through a bounded series of test vectors (covering rollovers)
        // We will test 110 cycles to cover tens, hundreds, and thousands rollovers
        for (i = 0; i < 115; i = i + 1) begin
            // Sample before clock edge to compute expected for next cycle
            exp_ena = calc_ena(q);
            exp_q = calc_next_q(q);

            @(posedge clk);
            #1; // Small delay for outputs to settle

            if (q !== exp_q) begin
                errors = errors + 1;
            end
            if (ena !== exp_ena) begin
                errors = errors + 1;
            end
        end

        // Test synchronous reset mid-operation
        reset = 1;
