`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        reset;
    wire [3:0] ena;
    wire [15:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Error tracking
    integer errors = 0;
    integer i;

    // Reference model variables to track expected BCD values
    reg [3:0] ref_ones      = 4'd0;
    reg [3:0] ref_tens      = 4'd0;
    reg [3:0] ref_hundreds  = 4'd0;
    reg [3:0] ref_thousands = 4'd0;

    wire [3:0] ref_ena_ones      = 1'b1;
    wire       ref_ena_tens      = (ref_ones == 4'd9);
    wire       ref_ena_hundreds  = (ref_tens == 4'd9) && ref_ena_tens;
    wire       ref_ena_thousands = (ref_hundreds == 4'd9) && ref_ena_hundreds;
    wire [3:0] ref_ena           = {ref_ena_thousands, ref_ena_hundreds, ref_ena_tens, ref_ena_ones};
    wire [15:0] ref_q            = {ref_thousands, ref_hundreds, ref_tens, ref_ones};

    // Task to update reference model on positive clock edge
    task update_reference;
        begin
            if (ref_ones == 4'd9)
                ref_ones <= 4'd0;
            else
                ref_ones <= ref_ones + 4'd1;

            if (ref_ena_tens) begin
                if (ref_tens == 4'd9)
                    ref_tens <= 4'd0;
                else
                    ref_tens <= ref_tens + 4'd1;
            end

            if (ref_ena_hundreds) begin
                if (ref_hundreds == 4'd9)
                    ref_hundreds <= 4'd0;
                else
                    ref_hundreds <= ref_hundreds + 4'd1;
            end

            if (ref_ena_thousands) begin
                if (ref_thousands == 4'd9)
                    ref_thousands <= 4'd0;
                else
                    ref_thousands <= ref_thousands + 4'd1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;

        // Apply reset
        #12;
        // Check outputs during reset
        if (q !== 16'h0000) errors = errors + 1;
        if (ena !== 4'b0001) errors = errors + 1;

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Run through multiple cycles and check against reference model
        for (i = 0; i < 1100; i = i + 1) begin
            @(posedge clk);
            #1; // Wait slightly after clock edge for outputs to settle

            // Check against expected values using case inequality (!==)
            if (q !== ref_q) begin
                errors = errors + 1;
            end
            if (ena !== ref_ena) begin
                errors = errors + 1;
            end

            // Update reference for the next cycle
            update_reference;
        end

        // Test synchronous reset mid-operation
        @(posedge clk);
        reset = 1;
        ref_ones      = 4'd0;
        ref_tens      = 4'd0;
        ref_hundreds  = 4'd0;
        ref_thousands = 4'd0;
        #1;
        if (q !== 16'h0000) errors = errors + 1;
        if (ena !== 4'b0001) errors = errors + 1;

        @(posedge clk);
        reset = 0;
        #1;

        // Final status report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

