module TopModule (
    input  wire        clk,
    input  wire        reset,
    output reg  [31:0] q
);

    // Galois LFSR with taps at positions 32, 22, 2, and 1.
    // Using 0-indexed vector [31:0]:
    // Tap 32 -> index 31
    // Tap 22 -> index 21
    // Tap 2  -> index 1
    // Tap 1  -> index 0

    wire feedback;
    assign feedback = q[0];

    always @(posedge clk) begin
        if (reset) begin
            q <= 32'h00000001;
        end else begin
            q <= {feedback, q[31:1]} ^ {32{feedback}} & 32'h80400003;
            // Equivalently, explicitly specifying the tap XORs:
            // q[31]   <= feedback;
            // q[30:22] <= q[31:23];
            // q[21]   <= q[22] ^ feedback;
            // q[20:2]  <= q[21:3];
            // q[1]    <= q[2] ^ feedback;
            // q[0]    <= q[1] ^ feedback;
        end
    end

endmodule

