module TopModule (
    input  wire        clk,
    input  wire        reset,
    output reg  [31:0] q
);

    // Standard 32-bit Galois LFSR with taps at positions 32, 22, 2, and 1.
    // In 0-indexed Verilog (bits [31:0]), the taps correspond to:
    // 32 -> bit 31
    // 22 -> bit 21
    //  2 -> bit 1
    //  1 -> bit 0
    //
    // For a Galois LFSR, on each clock cycle:
    // - If the shifting output bit (q[0]) is 1, the tap positions are XORed with a feedback polynomial.
    // - Specifically, next_q[i] = q[i+1] ^ (q[0] & tap[i])
    // - And next_q[31] = q[0] (since bit 32 is the feedback).

    always @(posedge clk) begin
        if (reset) begin
            q <= 32'h00000001;
        end else begin
            q[31]    <= q[0];
            q[30]    <= q[31];
            q[29]    <= q[30];
            q[28]    <= q[29];
            q[27]    <= q[28];
            q[26]    <= q[27];
            q[25]    <= q[26];
            q[24]    <= q[25];
            q[23]    <= q[24];
            q[22]    <= q[23];
            q[21]    <= q[22] ^ q[0]; // Tap at 22 (index 21)
            q[20]    <= q[21];
            q[19]    <= q[20];
            q[18]    <= q[19];
            q[17]    <= q[18];
            q[16]    <= q[17];
            q[15]    <= q[16];
            q[14]    <= q[15];
            q[13]    <= q[14];
            q[12]    <= q[13];
            q[11]    <= q[12];
            q[10]    <= q[11];
            q[9]     <= q[10];
            q[8]     <= q[9];
            q[7]     <= q[8];
            q[6]     <= q[7];
            q[5]     <= q[6];
            q[4]     <= q[5];
            q[3]     <= q[4];
            q[2]     <= q[3];
            q[1]     <= q[2] ^ q[0];  // Tap at 2 (index 1)
            q[0]     <= q[1] ^ q[0];  // Tap at 1 (index 0)
        end
    end

endmodule

