`timescale 1ns/1ps

module tb;

    // 1. Declare inputs as regs, outputs as wires
    reg         clk;
    reg         reset;
    wire [31:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk   (clk),
        .reset (reset),
        .q     (q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Reference model for 32-bit Galois LFSR (taps at 32, 22, 2, 1 -> indices 31, 21, 1, 0)
    function [31:0] lfsr_step;
        input [31:0] current_q;
        reg [31:0] next_q;
        reg feedback;
        begin
            feedback = current_q[0];
            next_q[31]    = feedback;
            next_q[30]    = current_q[31];
            next_q[29]    = current_q[30];
            next_q[28]    = current_q[29];
            next_q[27]    = current_q[28];
            next_q[26]    = current_q[27];
            next_q[25]    = current_q[26];
            next_q[24]    = current_q[25];
            next_q[23]    = current_q[24];
            next_q[22]    = current_q[23];
            next_q[21]    = current_q[22] ^ feedback; // Tap 22
            next_q[20]    = current_q[21];
            next_q[19]    = current_q[20];
            next_q[18]    = current_q[19];
            next_q[17]    = current_q[18];
            next_q[16]    = current_q[17];
            next_q[15]    = current_q[16];
            next_q[14]    = current_q[15];
            next_q[13]    = current_q[14];
            next_q[12]    = current_q[13];
            next_q[11]    = current_q[12];
            next_q[10]    = current_q[11];
            next_q[9]     = current_q[10];
            next_q[8]     = current_q[9];
            next_q[7]     = current_q[8];
            next_q[6]     = current_q[7];
            next_q[5]     = current_q[6];
            next_q[4]     = current_q[5];
            next_q[3]     = current_q[4];
            next_q[2]     = current_q[3];
            next_q[1]     = current_q[2] ^ feedback; // Tap 2
            next_q[0]     = current_q[1] ^ feedback; // Tap 1
            lfsr_step = next_q;
        end
    endfunction

    integer errors = 0;
    reg [31:0] expected_q;
    integer i;

    initial begin
        // Initialize signals
        reset = 1;
        clk = 0;
        expected_q = 32'h00000001;

        // Apply reset
        #12;
        // Check reset state using strict 4-state inequality
        if (q !== 32'h00000001) begin
            $display("ERROR: Reset state incorrect. Expected 32'h00000001, got %h", q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Run through 20 meaningful test vectors (clock cycles)
        for (i = 0; i < 20; i = i + 1) begin
            expected_q = lfsr_step(expected_q);
            @(posedge clk);
            #1; // Small delay to sample after clock edge

            if (q !== expected_q) begin
                $display("ERROR at cycle %0d: Expected %h, got %h", i, expected_q, q);
                errors = errors + 1;
            end
        end

        // Test asynchronous/synchronous reset interruption
        @(posedge clk);
        reset = 1;
        expected_q = 32'h00000001;
        #1;
        if (q !== 32'h00000001) begin
            $display("ERROR: Mid-stream reset failed. Expected 32'h00000001, got %h", q);
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        reset = 0;
        expected_q = lfsr_step(expected_q);
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            $display("ERROR after reset release: Expected %h, got %h", expected_q, q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

