`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        areset;
    reg        load;
    reg        ena;
    reg  [3:0] data;
    wire [3:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk    (clk),
        .areset (areset),
        .load   (load),
        .ena    (ena),
        .data   (data),
        .q      (q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg [3:0] expected_q;

    // Task to check output against expected value using case inequality
    task check_q(input [3:0] exp);
        begin
            @(posedge clk);
            #1; // small delay to allow outputs to settle after clock edge
            if (q !== exp) begin
                $display("ERROR: Time=%0t | areset=%b load=%b ena=%b data=%h | Expected q=%h, Got q=%h",
                         $time, areset, load, ena, data, exp, q);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;
        expected_q = 4'b0000;

        // Test 1: Asynchronous reset
        #2;
        areset = 1;
        #6;
        if (q !== 4'b0000) begin
            $display("ERROR: Asynchronous reset failed. Got q=%h", q);
            errors = errors + 1;
        end
        areset = 0;

        // Test 2: Synchronous Load
        @(posedge clk);
        load = 1;
        ena = 0;
        data = 4'b1011;
        expected_q = 4'b1011;
        check_q(expected_q);

        // Test 3: Hold state (load=0, ena=0)
        load = 0;
        ena = 0;
        expected_q = 4'b1011;
        check_q(expected_q);

        // Test 4: Enable shift right (ena=1)
        // q was 4'b1011 -> shift right -> {1'b0, 4'b1011[3:1]} = 4'b0101
        ena = 1;
        expected_q = 4'b0101;
        check_q(expected_q);

        // Test 5: Shift right again
        // q was 4'b0101 -> shift right -> 4'b0010
        expected_q = 4'b0010;
        check_q(expected_q);

        // Test 6: Priority check (load and ena both high -> load wins)
        load = 1;
        ena = 1;
        data = 4'b1110;
        expected_q = 4'b1110;
        check_q(expected_q);

        // Test 7: Disable load, continue shift
        load = 0;
        ena = 1;
        // q was 4'b1110 -> shift right -> 4'b0111
        expected_q = 4'b0111;
        check_q(expected_q);

        // Test 8: Asynchronous reset during operation
        areset = 1;
        #3;
        if (q !== 4'b0000) begin
            $display("ERROR: Asynchronous reset during operation failed. Got q=%h", q);
            errors = errors + 1;
        end
        areset = 0;

        // Final Result Display
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

