    always #5 clk = ~clk;

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;

        // Test 1: Asynchronous Reset check
        #2;
        areset = 1;
        #3;
        if (q !== 4'b0000) errors = errors + 1;

        #5;
        areset = 0;
        #2;
        if (q !== 4'b0000) errors = errors + 1;

        // Test 2: Synchronous Load check
        @(posedge clk);
        load = 1;
        ena = 0;
        data = 4'b1010;
        #2;
        // Should not update until posedge clk
        if (q !== 4'b0000) errors = errors + 1; 

        @(posedge clk);
        #2;
        if (q !== 4'b1010) errors = errors + 1;

        // Test 3: Priority check (load and ena both high -> load wins)
