module tb;
    reg clk;
    reg areset;
    reg load;
    reg ena;
    reg [3:0] data;
    wire [3:0] q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value using case inequality (!==)
    task check_q;
        input [3:0] expected;
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
            if (q !== expected) begin
                $display("Time %0t: Mismatch! Expected q = %b, Got q = %b (areset=%b, load=%b, ena=%b, data=%b)", 
                         $time, expected, q, areset, load, ena, data);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;

        // Test 1: Asynchronous Reset Test
        #2;
        areset = 1; // Assert async reset
        #3;
        if (q !== 4'b0000) begin
            $display("Time %0t: Async reset failed! Got q = %b", $time, q);
            errors = errors + 1;
        end
        areset = 0; // Deassert async reset

        @(posedge clk);
        #1;
        if (q !== 4'b0000) begin
            $display("Time %0t: Reset hold failed! Got q = %b", $time, q);
            errors = errors + 1;
        end

        // Test 2: Synchronous Load Test
        @(negedge clk);
        load = 1;
        ena = 0;
        data = 4'b1010;
        check_q(4'b1010);

        // Test 3: Hold state (load=0, ena=0)
        @(negedge clk);
        load = 0;
        ena = 0;
        data = 4'b0101; // should be ignored
        check_q(4'b1010);

        // Test 4: Shift Right Test (ena=1, load=0)
        // Current state: 4'b1010 -> Shift right -> 4'b0101
        @(negedge clk);
        ena = 1;
        check_q(4'b0101);

        // Shift again -> 4'b0010
        check_q(4'b0010);

        // Shift again -> 4'b0001
        check_q(4'b0001);

        // Shift again -> 4'b0000
        check_q(4'b0000);

        // Test 5: Priority Test (load and ena both asserted)
        // Load should take precedence over enable
        @(negedge clk);
        load = 1;
        ena = 1;
        data = 4'b1100;
        check_q(4'b1100);

        // Test 6: Asynchronous reset during operation
        @(negedge clk);
        load = 0;
        ena = 1;
        #2;
        areset = 1; // Mid-cycle async reset
        #3;
        if (q !== 4'b0000) begin
            $display("Time %0t: Mid-cycle async reset failed! Got q = %b", $time, q);
            errors = errors + 1;
        end
        areset = 0;

        #10;

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

