        #2;
        areset = 1;
        #3;
        if (q !== 4'b0000) begin
            $display("Time %0t: Async reset failed! Got q = %b", $time, q);
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        #5;

        // Test 2: Synchronous Load
        @(posedge clk);
        load = 1;
        ena = 0;
        data = 4'b1010;
