module TopModule (
    input  wire       clk,
    input  wire       reset,
    output reg  [4:0] q
);

    // 5-bit maximal-length Galois LFSR with taps at bit positions 5 and 3.
    // In a 0-indexed 5-bit register q[4:0]:
    // - Bit 4 corresponds to position 5 (tap)
    // - Bit 2 corresponds to position 3 (tap)
    // 
    // Galois LFSR shift operation with feedback bit exiting from q[0]:
    // - Next q[4]   = q[0] (since tap at 5)
    // - Next q[3]   = q[4]
    // - Next q[2]   = q[3] ^ q[0] (since tap at 3)
    // - Next q[1]   = q[2]
    // - Next q[0]   = q[1]

    always @(posedge clk) begin
        if (reset) begin
            q <= 5'b00001; // Active-high synchronous reset to 1 (or 5'b00001)
        end else begin
            q <= {q[0], q[4], q[3] ^ q[0], q[2], q[1]};
        end
    end

endmodule

