    integer errors = 0;
    integer step;
    reg [4:0] expected_q;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Golden model reference for 5-bit Galois LFSR with taps at positions 5 and 3 (0-indexed: q[4] and q[2])
    // Standard feedback for 5-bit maximal-length Galois LFSR with taps [5,3] (polynomial x^5 + x^3 + 1):
    // When shifting right (q[0] is output/feedback):
    // next_q[4] = q[0]
    // next_q[3] = q[4]
    // next_q[2] = q[3] ^ q[0]
    // next_q[1] = q[2]
    // next_q[0] = q[1]
    function [4:0] next_lfsr(input [4:0] current);
        begin
            next_lfsr = {current[0], current[4], current[3] ^ current[0], current[2], current[1]};
        end
    endfunction

    initial begin
        clk = 0;
        reset = 0;
        expected_q = 5'b00001;

        // Test 1: Reset behavior and asynchronous/synchronous checks
        @(posedge clk);
        reset = 1;
        #2;
        if (q !== 5'b00001) begin
            errors = errors + 1;
        end

        // Release reset on clock edge
        @(posedge clk);
        reset = 0;
        #2;
        // After reset deassertion, on the next posedge clk it should shift from 5'b00001

        // Test 2: Verify full cycle (maximal length 5-bit LFSR has 2^5 - 1 = 31 states)
        for (step = 0; step < 35; step = step + 1) begin
            @(posedge clk);
            #1; // Wait slightly after clock edge for DUT update

            // Compute expected value before the clock edge transition happened in the previous cycle
            // Wait, let's track expected_q synchronously:
            if (step == 0) begin
                // At first clock after reset release (reset was high at previous posedge, so q was 1)
                // Wait, let's trace precisely:
                // T=0: clk rises, reset=1 -> q <= 1
                // T=10: clk rises, reset=0 -> q should update to next_lfsr(1)
            end
        end

        // Let's do a structured self-checking loop starting from reset release
        // Re-initialize cleanly:
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        reset = 0;
        expected_q = 5'b00001;

        // Check reset state
        if (q !== 5'b00001) errors = errors + 1;

        // Step through multiple clock cycles and verify against golden model
        for (step = 0; step < 40; step = step + 1) begin
            @(posedge clk);
            #1; // sample after posedge
            expected_q = next_lfsr(expected_q);
