    // In 0-indexed terms (bits 4 down to 0): taps at positions 4 and 2.
    // Galois LFSR shift/XOR rule:
    // New bit [4] = old bit [0]
    // New bit [3] = old bit [4]
    // New bit [2] = old bit [3] ^ old bit [0] (tap at position 2 corresponds to bit 2)
    // New bit [1] = old bit [2]
    // New bit [0] = old bit [1] ^ old bit [0] (tap at position 4 corresponds to bit 0)
    function [4:0] lfsr_next;
        input [4:0] current;
        reg out_bit;
        begin
            out_bit = current[0];
            lfsr_next[4] = out_bit;
            lfsr_next[3] = current[4];
            lfsr_next[2] = current[3] ^ out_bit;
            lfsr_next[1] = current[2];
            lfsr_next[0] = current[1] ^ out_bit;
        end
    endfunction

    initial begin
        // Initialize inputs
        reset = 1;

        // Wait for a couple of clock edges under reset
        @(posedge clk);
        @(posedge clk);

