module TopModule (
    input  wire clk,
    input  wire areset,
    input  wire x,
    output wire z
);

    // One-hot encoding: State A = 2'b01, State B = 2'b10
    reg [1:0] state, next_state;

    parameter A = 2'b01;
    parameter B = 2'b10;

    // Asynchronous active-high reset, positive-edge triggered clock
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= A;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (Combinational)
    always @(*) begin
        case (state)
            A: begin
                if (x == 1'b0)
                    next_state = A;
                else
                    next_state = B;
            end
            B: begin
                next_state = B;
            end
            default: begin
                next_state = A;
            end
        endcase
    end

    // Mealy output logic (Combinational)
    // A --x=0 (z=0)--> A
    // A --x=1 (z=1)--> B
    // B --x=0 (z=1)--> B
    // B --x=1 (z=0)--> B
    assign z = (state == A && x == 1'b1) || (state == B && x == 1'b0);

endmodule

