        areset = 1;
        #3;
        if (dut.state !== 2'b01) begin
            $display("Reset Fail: State is not A (2'b01), got %b", dut.state);
            errors = errors + 1;
        end

        // Deassert reset synchronously on negative edge to avoid race conditions
        @(negedge clk);
        areset = 0;
        #1;

        // Test 2: State A behavior
        // State A, x=0 -> should stay A, z=0
        check_transition(0, 0);

        // State A, x=0 -> should stay A, z=0
        check_transition(0, 0);

        // State A, x=1 -> should transition to B, z=1 (2's complementer first '1' found)
        check_transition(1, 1);

        // Test 3: State B behavior (once in B, stay in B indefinitely)
        // State B, x=1 -> should stay B, z=0
        check_transition(1, 0);

        // State B, x=0 -> should stay B, z=1
        check_transition(0, 1);

        // State B, x=1 -> should stay B, z=0
        check_transition(1, 0);

        // State B, x=0 -> should stay B, z=1
        check_transition(0, 1);

        // Test 4: Asynchronous reset recovery and re-entry
        areset = 1;
        #4;
        areset = 0;
        #1;
        if (dut.state !== 2'b01) begin
            $display("Reset recovery Fail: State is not A, got %b", dut.state);
            errors = errors + 1;
        end

