`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply input and check expected output on the next clock edge
    task apply_and_check(input reg in_x, input reg expected_z);
        begin
            x = in_x;
            @(posedge clk);
            #1; // Small delay for outputs to settle after clock edge
            if (z !== expected_z) begin
                $display("Mismatch: time=%0t | x=%b | expected_z=%b | got_z=%b", $time, in_x, expected_z, z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Test asynchronous reset
        areset = 1;
        #12;
        if (z !== 1'b0) begin
            $display("Reset check failed: z is not 0 during reset");
            errors = errors + 1;
        end
        areset = 0;
        #3;

        // Sequence test for 2's complementer Mealy FSM
        // State A: receives first 1, outputs 1, transitions to B. Then stays in B and inverts bits.

        // From State A (after reset):
        // x = 0 -> should output 0, stay in A
        apply_and_check(1'b0, 1'b0);

        // x = 0 -> should output 0, stay in A
        apply_and_check(1'b0, 1'b0);

        // x = 1 -> should output 1, transition to B
        apply_and_check(1'b1, 1'b1);

        // Now in State B:
        // x = 0 -> should output 1, stay in B
        apply_and_check(1'b0, 1'b1);

        // x = 1 -> should output 0, stay in B
        apply_and_check(1'b1, 1'b0);

        // x = 1 -> should output 0, stay in B
        apply_and_check(1'b1, 1'b0);

        // x = 0 -> should output 1, stay in B
        apply_and_check(1'b0, 1'b1);

        // Test reset mid-operation
        areset = 1;
        @(posedge clk);
        #1;
        if (z !== 1'b0) begin
            $display("Mid-op reset check failed");
            errors = errors + 1;
        end
        areset = 0;

        // After reset, test x = 1 again -> should output 1
        apply_and_check(1'b1, 1'b1);

        // Final result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

