module TopModule (
    input  wire clk,
    input  wire areset,
    input  wire x,
    output reg  z
);

    // State encoding for the Moore FSM
    // S0: Saw no '1's yet (or reset state). Future bits are just inverted (0->0, 1->1 until first 1).
    // S1: Saw the first '1'. Future bits are inverted (0->1, 1->0).
    localparam S0 = 1'b0;
    localparam S1 = 1'b1;

    reg state, next_state;

    // Sequential state transition logic with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end

    // Combinational next-state and output logic
    always @(*) begin
        case (state)
            S0: begin
                // In S0, output is directly the input (0 stays 0, first 1 stays 1)
                z = x;
                // If input is 1, transition to S1; otherwise stay in S0
                if (x == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end

            S1: begin
                // In S1, output is the inverted input (0 becomes 1, 1 becomes 0)
                z = ~x;
                // Stay in S1 indefinitely for subsequent bits
                next_state = S1;
            end

            default: begin
                z = 1'b0;
                next_state = S0;
            end
        endcase
    end

endmodule

