    task apply_reset;
        begin
            areset = 1;
            x = 0;
            #12;
            areset = 0;
            #3;
        end
    endtask

    initial begin
        clk = 0;
        areset = 0;
        x = 0;

        // Test 1: Asynchronous reset test during operation
        apply_reset();

        // Feed sequence: 3'b000 (0) -> expected 2's comp: 000
        @(posedge clk); x = 1'b0; #1;
        if (z !== 1'b0) errors = errors + 1;

        @(posedge clk); x = 1'b0; #1;
        if (z !== 1'b0) errors = errors + 1;

        // Assert areset mid-stream to check async reset behavior
        areset = 1;
        #4;
        if (z !== 1'b0) errors = errors + 1; // Assuming reset forces output or state
        areset = 0;
        #6;

        // Test 2: 2's complement of 3'b011 (decimal 3) -> expected: 101 (-3)
        // LSB first: x=1, x=1, x=0
        apply_reset();

        // LSB = 1 (first '1')
        @(posedge clk); x = 1'b1; #1;
        if (z !== 1'b1) errors = errors + 1; // 1 -> 1

        // Next bit = 1
        @(posedge clk); x = 1'b1; #1;
        if (z !== 1'b0) errors = errors + 1; // inverted: 1 -> 0

        // MSB = 0
        @(posedge clk); x = 1'b0; #1;
        if (z !== 1'b1) errors = errors + 1; // inverted: 0 -> 1

        // Test 3: 2's complement of 4'b1010 (decimal -6) -> expected: 0110 (+6)
        // LSB first: 0, 1, 0, 1
        apply_reset();

        // Bit 0 (LSB): 0 -> stays 0, stays S0
        @(posedge clk); x = 1'b0; #1;
        if (z !== 1'b0) errors = errors + 1;

        // Bit 1: 1 -> stays 1, transitions to S1
        @(posedge clk); x = 1'b1; #1;
        if (z !== 1'b1) errors = errors + 1;

        // Bit 2: 0 -> inverted to 1 (S1)
        @(posedge clk); x = 1'b0; #1;
        if (z !== 1'b1) errors = errors + 1;

        // Bit 3 (MSB): 1 -> inverted to 0 (S1)
        @(posedge clk); x = 1'b1; #1;
        if (z !== 1'b0) errors = errors + 1;

        // Test 4: All zeros input stream
        apply_reset();
        repeat(5) begin
            @(posedge clk); x = 1'b0; #1;
            if (z !== 1'b0) errors = errors + 1;
        end

        // Final Result Report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

