`timescale 1ns/1ps

module tb;
    reg clk;
    reg areset;
    reg x;
    wire z;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply reset
    task apply_reset;
        begin
            areset = 1;
            x = 0;
            @(posedge clk);
            @(posedge clk);
            areset = 0;
            @(posedge clk);
        end
    endtask

    initial begin
        clk = 0;
        areset = 1;
        x = 0;

        // Test 1: Reset behavior
        #12;
        areset = 0; // release reset
        @(posedge clk);
        // At reset release, state machine should be in '0' state, output for LSB 0 should be 0
        x = 0; 
        @(posedge clk);
        #1;
        if (z !== 1'b0) errors = errors + 1;

        // Test 2: 2's complement of 0000 (0) -> should be 0000
        // Stream: LSB first -> 0, 0, 0, 0
        // Expected out: 0, 0, 0, 0
        apply_reset();

        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;

        // Test 3: 2's complement of 0011 (3 in decimal) -> should be 1101 (-3 in 4-bit)
        // Stream: LSB first -> 1, 1, 0, 0
        // Expected out: 1, 1, 0, 1
        apply_reset();

        x = 1'b1; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;
        x = 1'b1; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;

        // Test 4: 2's complement of 1000 (-8 in 4-bit) -> should be 1000 (-8)
        // Stream: LSB first -> 0, 0, 0, 1
        // Expected out: 0, 0, 0, 1
        apply_reset();

        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b1; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;

        // Test 5: Asynchronous reset during operation
        apply_reset();
        x = 1'b1; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;
        x = 1'b1; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;

        // Assert reset mid-stream
        areset = 1;
        #3;
        if (z !== 1'b0) errors = errors + 1; // Assuming reset forces output to 0 or state resets

        areset = 0;
        @(posedge clk);
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;

        // Final result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

