`timescale 1ns/1ps
module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;
    reg [7:0] input_data; // To hold the input number
    reg [7:0] expected_output; // To hold the expected output
    integer i;

    initial begin
        // Initialize signals
        clk = 0;
        areset = 1; // Assert reset
        x = 0;
        #10;

        // Release reset
        areset = 0;
        #10;

        // Test case 1: Input 0 (2's complement of 0 is 0)
        input_data = 8'b00000000;
        for (i = 0; i < 8; i = i + 1) begin
            x = input_data[i];
            #10; // Wait for one clock cycle
        end
        expected_output = 8'b00000000;
        #10; // Wait for output to stabilize
        if (z !== expected_output[0]) errors = errors + 1;

        // Test case 2: Input 1 (2's complement of 1 is 11111111)
        input_data = 8'b00000001;
        for (i = 0; i < 8; i = i + 1) begin
            x = input_data[i];
            #10; // Wait for one clock cycle
        end
        expected_output = 8'b11111111;
        #10; // Wait for output to stabilize
        if (z !== expected_output[0]) errors = errors + 1;

        // Test case 3: Input 5 (2's complement of 5 is 11111011)
        input_data = 8'b00000101;
        for (i = 0; i < 8; i = i + 1) begin
            x = input_data[i];
            #10; // Wait for one clock cycle
        end
        expected_output = 8'b11111011;
        #10; // Wait for output to stabilize
        if (z !== expected_output[0]) errors = errors + 1;

        // Test case 4: Input 255 (2's complement of 255 is 00000001)
        input_data = 8'b11111111;
        for (i = 0; i < 8; i = i + 1) begin
            x = input_data[i];
            #10; // Wait for one clock cycle
        end
        expected_output = 8'b00000001;
        #10; // Wait for output to stabilize
        if (z !== expected_output[0]) errors = errors + 1;

        // Test case 5: Input 127 (2's complement of 127 is 10000001)
        input_data = 8'b01111111;
        for (i = 0; i < 8; i = i + 1) begin
            x = input_data[i];
            #10; // Wait for one clock cycle
        end
        expected_output = 8'b10000001;
        #10; // Wait for output to stabilize
        if (z !== expected_output[0]) errors = errors + 1;

        // Assert reset again
        areset = 1;
        #10;

        // Final check for errors
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    // Clock generation
    always #5 clk = ~clk; // 10ns clock period
endmodule

