    input        w,
    output       Y1,
    output       Y3
);

    // One-hot state assignments:
    // y[0] = A (000001)
    // y[1] = B (000010)
    // y[2] = C (000100)
    // y[3] = D (001000)
    // y[4] = E (010000)
    // y[5] = F (100000)

    // Transitions into state B (y[1]):
    // A --1--> B  (y[0] & w)
