design_code:
module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire data,
    output reg  start_shifting
);

    // State encoding for FSM looking for "1101"
    // S_IDLE: No relevant bits matched
    // S_1:    Matched "1"
    // S_11:   Matched "11"
    // S_110:  Matched "110"
    // S_DONE: Matched "1101" (terminal state)
    localparam [2:0] 
        S_IDLE = 3'd0,
        S_1    = 3'd1,
        S_11   = 3'd2,
        S_110  = 3'd3,
        S_DONE = 3'd4;

    reg [2:0] current_state, next_state;

    // Sequential state transition and output logic
    always @(posedge clk) begin
        if (reset) begin
            current_state  <= S_IDLE;
            start_shifting <= 1'b0;
        end else begin
            current_state <= next_state;
            if (next_state == S_DONE) begin
                start_shifting <= 1'b1;
            end
        end
    end

    // Combinational next-state logic
    always @* begin
        next_state = current_state;

        case (current_state)
            S_IDLE: begin
                if (data)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end

            S_1: begin
                if (data)
                    next_state = S_11;
                else
                    next_state = S_IDLE;
            end

            S_11: begin
                if (data)
                    next_state = S_11; // overlapping sequence support (e.g., 11101)
                else
                    next_state = S_110;
            end

            S_110: begin
                if (data)
                    next_state = S_DONE;
                else
                    next_state = S_IDLE;
            end

            S_DONE: begin
                next_state = S_DONE; // Stay in DONE state forever until reset
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

test_code:
`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply one bit of data synchronously
    task drive_bit(input bit val);
        begin
            @(posedge clk);
            #1; // small offset after clock edge
            data = val;
        end
    endtask

    // Task to check expected output
    task check_output(input bit expected);
        begin
            // Wait slightly after clock edge to sample stable output
            @(posedge clk);
            #2;
            if (start_shifting !== expected) begin
                $display("Time %0t: Mismatch! data=%b, expected start_shifting=%b, got=%b", 
                         $time, data, expected, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Apply reset
        #12;
        reset = 0;

        // Check initial state after reset
        #2;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Reset failed! start_shifting is %b", $time, start_shifting);
            errors = errors + 1;
        end

        // Test Sequence 1: Incorrect stream (1, 0, 1, 1) -> should not trigger
        drive_bit(1); check_output(0);
        drive_bit(0); check_output(0);
        drive_bit(1); check_output(0);
        drive_bit(1); check_output(0);

        // Test Sequence 2: Correct stream (1, 1, 0, 1) -> should trigger start_shifting = 1
        drive_bit(1); check_output(0); // '1'
        drive_bit(1); check_output(0); // '11'
        drive_bit(0); check_output(0); // '110'
        drive_bit(1); check_output(1); // '1101' -> triggers

        // Test Sequence 3: Verify it stays 1 forever, even with arbitrary data
        drive_bit(0); check_output(1);
        drive_bit(0); check_output(1);
        drive_bit(1); check_output(1);

        // Test Sequence 4: Reset behavior
        @(posedge clk);
        reset = 1;
        #2;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Synchronous reset failed to clear start_shifting!", $time);
            errors = errors + 1;
        end

        // Deassert reset and test another pattern (overlapping: 11101)
        @(posedge clk);
        reset = 0;

        drive_bit(1); check_output(0);
        drive_bit(1); check_output(0);
        drive_bit(1); check_output(0); // second '1' in 111
        drive_bit(0); check_output(0); // '0'
        drive_bit(1); check_output(1); // '1' -> triggers via overlap

        #20;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

