`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // Instantiate TopModule as required by the contract
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply one clock cycle with a specific data input and check output
    task apply_bit(input bit d, input bit expected_out);
        begin
            data = d;
            @(posedge clk);
            #1; // small delay to allow outputs to settle
            if (start_shifting !== expected_out) begin
                $display("Mismatch at time %0t: data=%b, expected start_shifting=%b, got=%b", 
                         $time, d, expected_out, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        data = 0;

        // Hold reset for a few cycles
        @(posedge clk);
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Reset error: start_shifting not 0 during reset");
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        @(posedge clk);

        // Test 1: Simple non-matching stream followed by matching "1101"
        // Stream: 0, 1, 0, 1, 1, 0, 1
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b1, 1'b0); // Matches '1' (S_1)
        apply_bit(1'b1, 1'b0); // Matches '11' (S_11)
        apply_bit(1'b0, 1'b0); // Matches '110' (S_110)
        apply_bit(1'b1, 1'b1); // Matches '1101' -> S_DONE, start_shifting goes high

        // Test 2: Verify it stays high forever in S_DONE state
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b1, 1'b1);

        // Test 3: Synchronous Reset test while in DONE state
        reset = 1;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Reset error: start_shifting not 0 after synchronous reset from DONE");
            errors = errors + 1;
        end
        reset = 0;
        @(posedge clk);

        // Test 4: Overlapping sequence test (e.g., 11101)
        // Stream: 1, 1, 1, 0, 1
        apply_bit(1'b1, 1'b0); // S_1
        apply_bit(1'b1, 1'b0); // S_11 (first '1')
        apply_bit(1'b1, 1'b0); // S_11 (second '1', self-loop)
        apply_bit(1'b0, 1'b0); // S_110
        apply_bit(1'b1, 1'b1); // S_DONE

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

