module tb;

    // Inputs declared as regs
    reg clk;
    reg reset;
    reg data;

    // Outputs declared as wires
    wire start_shifting;

    // Error counter for self-checking
    integer errors = 0;

    // Instantiate the DUT
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to apply one bit of data synchronously on the positive edge
    task drive_bit(input bit val);
        begin
            @(posedge clk);
            #1; // small offset for sampling
            data = val;
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Hold reset for a few cycles
        #12;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Release reset
        reset = 0;
        @(posedge clk);

        // Test 1: Feed incorrect sequence "1000", start_shifting should remain 0
        drive_bit(1'b1);
        drive_bit(1'b0);
        drive_bit(1'b0);
        drive_bit(1'b0);
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Test 2: Feed "1101" -> Should trigger start_shifting = 1
        drive_bit(1'b1); // '1'
        drive_bit(1'b1); // '11'
        drive_bit(1'b0); // '110'
        drive_bit(1'b1); // '1101' - found!
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test 3: Keep feeding random data after sequence is found; it should stay 1 (forever until reset)
        drive_bit(1'b0);
        drive_bit(1'b0);
        drive_bit(1'b1);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test 4: Apply synchronous reset, start_shifting should return to 0
        @(posedge clk);
        reset = 1;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Release reset and test an overlapping sequence "11101"
        @(posedge clk);
        reset = 0;
        drive_bit(1'b1); // 1
        drive_bit(1'b1); // 11
        drive_bit(1'b1); // 111 (should stay in S_11)
        drive_bit(1'b0); // 1110
        drive_bit(1'b1); // 11101 -> found!
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Final check and report
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

