module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire data,
    output reg  start_shifting
);

    // State encoding for FSM looking for "1101"
    // S_IDLE: No relevant bits matched yet
    // S_1:    Matched "1"
    // S_11:   Matched "11"
    // S_110:  Matched "110"
    // S_FOUND: Matched "1101" (terminal state)
    localparam [2:0] 
        S_IDLE  = 3'b000,
        S_1     = 3'b001,
        S_11    = 3'b010,
        S_110   = 3'b011,
        S_FOUND = 3'b100;

    reg [2:0] current_state, next_state;

    // Sequential state transition logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= S_IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational next-state and output logic
    always @(*) begin
        // Default assignments
        next_state = current_state;
        start_shifting = 1'b0;

        case (current_state)
            S_IDLE: begin
                if (data)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end

            S_1: begin
                if (data)
                    next_state = S_11;
                else
                    next_state = S_IDLE;
            end

            S_11: begin
                if (data)
                    next_state = S_11;  // Still "11" (overlapping sequence like 11101)
                else
                    next_state = S_110;
            end

            S_110: begin
                if (data)
                    next_state = S_FOUND;
                else
                    next_state = S_IDLE;
            end

            S_FOUND: begin
                start_shifting = 1'b1;
                next_state = S_FOUND; // Stay here forever until reset
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

