`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // Instantiate the Unit Under Test (UUT)
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Task to apply a single bit and wait for positive edge
    task apply_bit(input b);
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
            data = b;
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        data = 0;

        // Apply reset
        @(posedge clk);
        reset = 1;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        @(posedge clk);
        reset = 0;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Test 1: Simple non-matching sequence followed by correct sequence "1101"
        // Stream: 0, 0, 1, 0, 1, 1, 0, 1
        apply_bit(0);
        apply_bit(0);
        apply_bit(1);
        apply_bit(0);
        if (start_shifting !== 1'b0) errors = errors + 1;

        apply_bit(1);
        apply_bit(1);
        apply_bit(0);
        apply_bit(1); // Should hit FOUND here
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test 2: Check sticky property (stays 1 forever until reset even with random data)
        apply_bit(0);
        apply_bit(0);
        apply_bit(1);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test 3: Synchronous reset while in FOUND state
        @(posedge clk);
        reset = 1;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        @(posedge clk);
        reset = 0;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Test 4: Overlapping sequence test: "11101"
        // Stream: 1, 1, 1, 0, 1
        // State machine handles "11" -> "11" on data=1, then "110", then "FOUND"
        apply_bit(1);
        apply_bit(1);
        apply_bit(1);
        if (start_shifting !== 1'b0) errors = errors + 1;
        apply_bit(0);
        apply_bit(1);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test 5: Another reset check
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        reset = 0;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Test 6: Partial match failure (e.g., 1100 should reset search to IDLE or appropriate)
        apply_bit(1);
        apply_bit(1);
        apply_bit(0);
        apply_bit(0); // Fails the 1101 sequence
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Complete the sequence now: 1, 1, 0, 1
        apply_bit(1);
        apply_bit(1);
        apply_bit(0);
        apply_bit(1);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

