`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    // Instantiate TopModule as required
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply one bit and check output on the next clock edge
    task apply_bit(input bit b, input bit expected_out);
        begin
            data = b;
            @(posedge clk);
            #1; // small delay for propagation
            if (start_shifting !== expected_out) begin
                $display("Mismatch at time %0t: data=%b, expected start_shifting=%b, got=%b", 
                         $time, b, expected_out, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Apply reset for a few cycles
        @(posedge clk);
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Reset check failed: start_shifting is not 0");
            errors = errors + 1;
        end

        // Release reset
        reset = 0;
        @(posedge clk);

        // Test Case 1: Incorrect sequence ("0000") -> should remain 0
        $display("Test 1: Feeding 0000");
        apply_bit(0, 0);
        apply_bit(0, 0);
        apply_bit(0, 0);
        apply_bit(0, 0);

        // Test Case 2: Partial sequence then fail ("1100") -> should reset search path
        $display("Test 2: Feeding 1100");
        apply_bit(1, 0); // S_1
        apply_bit(1, 0); // S_11
        apply_bit(0, 0); // S_110
        apply_bit(0, 0); // Back to S_IDLE

        // Test Case 3: Overlapping sequence leading to success ("11101")
        // "111" should keep state at S_11, then '0' goes to S_110, then '1' goes to S_DONE
        $display("Test 3: Feeding 11101");
        apply_bit(1, 0); // S_1
        apply_bit(1, 0); // S_11
        apply_bit(1, 0); // S_11 (overlapping '1')
        apply_bit(0, 0); // S_110
        apply_bit(1, 1); // S_DONE -> start_shifting goes high!

        // Test Case 4: Verify start_shifting stays high forever and ignores further data
        $display("Test 4: Checking persistence in S_DONE");
        apply_bit(0, 1);
        apply_bit(0, 1);
        apply_bit(1, 1);

        // Test Case 5: Synchronous reset test while in S_DONE
        $display("Test 5: Asserting synchronous reset");
        reset = 1;
        data = 0;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Synchronous reset failed to clear start_shifting");
            errors = errors + 1;
        end

        // Release reset and test a clean successful sequence "1101"
        reset = 0;
        @(posedge clk);
        $display("Test 6: Clean sequence 1101");
        apply_bit(1, 0);
        apply_bit(1, 0);
        apply_bit(0, 0);
        apply_bit(1, 1);

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

