module TopModule (
    input  [6:0] y,
    input        w,
    output       Y1,
    output       Y3
);

    // One-hot state assignment:
    // y[0] = A (000001)
    // y[1] = B (000010)
    // y[2] = C (000100)
    // y[3] = D (001000)
    // y[4] = E (010000)
    // y[5] = F (100000)
    // (y[6] is unused in the 6-state machine)

    // Transitions into State B (y[1], output Y1):
    // A --0--> B (y[0] and ~w)
    assign Y1 = y[0] & ~w;

    // Transitions into State D (y[3], output Y3):
    // B --1--> D (y[1] and w)
    // C --1--> D (y[2] and w)
    // E --1--> D (y[4] and w)
    // F --1--> D (y[5] and w)
    assign Y3 = (y[1] | y[2] | y[4] | y[5]) & w;

endmodule

