`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires according to spec
    reg [6:0] y;
    reg w;
    wire Y1;
    wire Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;

    // Expected value variables
    reg exp_Y1;
    reg exp_Y3;

    // Task to check outputs against expected values using case inequality (!==)
    task check_outputs;
        input [6:0] current_y;
        input current_w;
        input expected_y1;
        input expected_y3;
        begin
            y = current_y;
            w = current_w;
            #1; // Allow combinatorial propagation

            exp_Y1 = expected_y1;
            exp_Y3 = expected_y3;

            if (Y1 !== exp_Y1) begin
                $display("Mismatch for y=%b, w=%b: Y1 got %b, expected %b", y, w, Y1, exp_Y1);
                errors = errors + 1;
            end
            if (Y3 !== exp_Y3) begin
                $display("Mismatch for y=%b, w=%b: Y3 got %b, expected %b", y, w, Y3, exp_Y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 7'b0;
        w = 1'b0;
        #5;

        // Based on the FSM specification:
        // One-hot state assignments:
        // A = y[0] = 6'b000001 (or 7'b0000001 if y is 7 bits)
        // B = y[1] = 6'b000010
        // C = y[2] = 6'b000100
        // D = y[3] = 6'b001000
        // E = y[4] = 6'b010000
        // F = y[5] = 6'b100000
        // (y[6] is unused or part of 7-bit bus)
        //
        // Transitions & Next States:
        // State A (y[0]=1): w=0 -> B (y[1]=1), w=1 -> A (y[0]=1)
        // State B (y[1]=1): w=0 -> C (y[2]=1), w=1 -> D (y[3]=1)
        // State C (y[2]=1): w=0 -> E (y[4]=1), w=1 -> D (y[3]=1)
        // State D (y[3]=1): w=0 -> F (y[5]=1), w=1 -> A (y[0]=1)
        // State E (y[4]=1): w=0 -> E (y[4]=1), w=1 -> D (y[3]=1)
        // State F (y[5]=1): w=0 -> C (y[2]=1), w=1 -> D (y[3]=1)
        //
        // Next-state signals Y1 and Y3 correspond to y[1] (State B) and y[3] (State D).
        // Let's derive expected Y1 (State B next) and Y3 (State D next):
        // B is next state when:
        // - In A and w=0 -> y[0] & ~w
        //
        // D is next state when:
        // - In B and w=1 -> y[1] & w
        // - In C and w=1 -> y[2] & w
        // - In D and w=1 -> y[3] & w
        // - In E and w=1 -> y[4] & w
        // - In F and w=1 -> y[5] & w
        // (So Y3 = w & (y[1] | y[2] | y[3] | y[4] | y[5]))

        // Test vectors: Exhaustive combinations of states and w

        // State A (7'b0000001)
        check_outputs(7'b0000001, 1'b0, 1'b1, 1'b0); // w=0 -> goes to B (Y1=1)
        check_outputs(7'b0000001, 1'b1, 1'b0, 1'b0); // w=1 -> goes to A

        // State B (7'b0000010)
        check_outputs(7'b0000010, 1'b0, 1'b0, 1'b0); // w=0 -> goes to C
        check_outputs(7'b0000010, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // State C (7'b0000100)
        check_outputs(7'b0000100, 1'b0, 1'b0, 1'b0); // w=0 -> goes to E
        check_outputs(7'b0000100, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // State D (7'b0001000)
        check_outputs(7'b0001000, 1'b0, 1'b0, 1'b0); // w=0 -> goes to F
        check_outputs(7'b0001000, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // State E (7'b0010000)
        check_outputs(7'b0010000, 1'b0, 1'b0, 1'b0); // w=0 -> goes to E
        check_outputs(7'b0010000, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // State F (7'b0100000)
        check_outputs(7'b0100000, 1'b0, 1'b0, 1'b0); // w=0 -> goes to C
        check_outputs(7'b0100000, 1'b1, 1'b0, 1'b1); // w=1 -> goes to D (Y3=1)

        // Edge case: Unused/invalid one-hot states (e.g. all zeros or multiple bits)
        check_outputs(7'b0000000, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b1111111, 1'b1, 1'b0, 1'b1);

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

