module TopModule (
    input        in,
    input  [1:0] state,
    output [1:0] next_state,
    output       out
);

    // State encoding: A=2'b00, B=2'b01, C=2'b10, D=2'b11
    // A: Next state in=0 -> A (00), in=1 -> B (01). Output = 0
    // B: Next state in=0 -> C (10), in=1 -> B (01). Output = 0
    // C: Next state in=0 -> A (00), in=1 -> D (11). Output = 0
    // D: Next state in=0 -> C (10), in=1 -> B (01). Output = 1

    reg [1:0] next_state_logic;
    reg       out_logic;

    always @(*) begin
        case (state)
            2'b00: begin // State A
                next_state_logic = in ? 2'b01 : 2'b00;
                out_logic        = 1'b0;
            end
            2'b01: begin // State B
                next_state_logic = in ? 2'b01 : 2'b10;
                out_logic        = 1'b0;
            end
            2'b10: begin // State C
                next_state_logic = in ? 2'b11 : 2'b00;
                out_logic        = 1'b0;
            end
            2'b11: begin // State D
                next_state_logic = in ? 2'b01 : 2'b10;
                out_logic        = 1'b1;
            end
            default: begin
                next_state_logic = 2'b00;
                out_logic        = 1'b0;
            end
        endcase
    end

    assign next_state = next_state_logic;
    assign out        = out_logic;

endmodule

