module tb;
    reg in;
    reg [1:0] state;
    wire [1:0] next_state;
    wire out;

    TopModule dut (
        .in(in),
        .state(state),
        .next_state(next_state),
        .out(out)
    );

    integer errors = 0;

    // Task to check expected values
    task check;
        input reg exp_in;
        input reg [1:0] exp_state;
        input reg [1:0] exp_next_state;
        input reg exp_out;
        begin
            in = exp_in;
            state = exp_state;
            #1; // Allow combinational propagation

            if (next_state !== exp_next_state) begin
                $display("Mismatch: in=%b, state=%b | expected next_state=%b, got %b", 
                         exp_in, exp_state, exp_next_state, next_state);
                errors = errors + 1;
            end

            if (out !== exp_out) begin
                $display("Mismatch: in=%b, state=%b | expected out=%b, got %b", 
                         exp_in, exp_state, exp_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Test State A (2'b00)
        // A | A, B | 0
        check(1'b0, 2'b00, 2'b00, 1'b0);
        check(1'b1, 2'b00, 2'b01, 1'b0);

        // Test State B (2'b01)
        // B | C, B | 0
        check(1'b0, 2'b01, 2'b10, 1'b0);
        check(1'b1, 2'b01, 2'b01, 1'b0);

        // Test State C (2'b10)
        // C | A, D | 0
        check(1'b0, 2'b10, 2'b00, 1'b0);
        check(1'b1, 2'b10, 2'b11, 1'b0);

        // Test State D (2'b11)
        // D | C, B | 1
        check(1'b0, 2'b11, 2'b10, 1'b1);
        check(1'b1, 2'b11, 2'b01, 1'b1);

        // Test undefined / unused corner cases if any (e.g., robust checking against X/Z handling via 4-state logic)
        // By using `!==` in the check task, any 'x' or 'z' on outputs will automatically trigger an error.

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule

