        // B (2'b01): in=0 -> next C, out=0 | in=1 -> next B, out=0
        // C (2'b10): in=0 -> next A, out=0 | in=1 -> next D, out=0
        // D (2'b11): in=0 -> next C, out=1 | in=1 -> next B, out=1

        // State A
        state = 2'b00;
        in = 1'b0; check_outputs(2'b00, 1'b0);
        in = 1'b1; check_outputs(2'b01, 1'b0);

        // State B
        state = 2'b01;
        in = 1'b0; check_outputs(2'b10, 1'b0); // Spec: B, in=0 -> C (2'b10)
        in = 1'b1; check_outputs(2'b01, 1'b0); // Spec: B, in=1 -> B (2'b01)

