module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg         clk;
    reg         load;
    reg  [ 1:0] ena;
    reg  [99:0] data;
    wire [99:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk  (clk),
        .load (load),
        .ena  (ena),
        .data (data),
        .q    (q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    reg [99:0] expected_q;

    // Task to check output
    task check_output(input [99:0] exp);
        begin
            @(posedge clk);
            #1; // Wait slightly after clock edge for DUT update
            if (q !== exp) begin
                $display("Time %0t: Mismatch! Got 0%h, Expected 0%h (load=%b, ena=%b)", 
                         $time, q, exp, load, ena);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking:
    initial begin
        // Initialize signals
        load = 0;
        ena  = 2'b00;
        data = 100'h0;

        // Apply reset / initial load
        @(posedge clk);
        load = 1;
        data = 100'h123456789ABCDEF0123456789A; // Some pattern with top bit set/clear
        expected_q = data;
        check_output(expected_q);

        // Test no rotation (ena = 2'b00)
        load = 0;
        ena  = 2'b00;
        expected_q = expected_q;
        check_output(expected_q);

        // Test no rotation (ena = 2'b11)
        ena  = 2'b11;
        expected_q = expected_q;
        check_output(expected_q);

        // Test rotate right by one bit (ena = 2'b01) a few times
        ena = 2'b01;
