        // Test 1: Reset / Initial load
        data = 100'h1; // LSB set
        load = 1'b1;
        ena = 2'b00;
        @(posedge clk);
        #1;
        load = 1'b0;
        if (q !== 100'h1) begin
            errors = errors + 1;
        end

        // Test 2: Rotate Left (2'b10) by 1 bit. 
        // 100'h1 shifted left by 1 with wrap should be 100'h2
        ena = 2'b10;
        @(posedge clk);
        #1;
        if (q !== 100'h2) begin
            errors = errors + 1;
        end

        // Test 3: Rotate Right (2'b01) by 1 bit.
        // 100'h2 rotated right by 1 should go back to 100'h1
        ena = 2'b01;
        @(posedge clk);
        #1;
        if (q !== 100'h1) begin
            errors = errors + 1;
        end

        // Test 4: Check 2'b00 (no rotation)
        ena = 2'b00;
        @(posedge clk);
        #1;
        if (q !== 100'h1) begin
            errors = errors + 1;
        end

        // Test 5: Check 2'b11 (no rotation per spec)
        ena = 2'b11;
        @(posedge clk);
        #1;
        if (q !== 100'h1) begin
            errors = errors + 1;
        end

        // Test 6: MSB rotation wrap-around check for Left rotate
        // Load MSB set: 100'h8000000000000000000000000 (bit 99)
        load = 1'b1;
        data = {1'b1, 99'h0};
        ena = 2'b00;
        @(posedge clk);
