`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    reg in;
    wire out;

    // Error counter
    integer errors = 0;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to check output against expected value using case inequality (!==)
    task check_output;
        input expected_out;
        begin
            @(posedge clk);
            #1; // Small delay to allow combinatorial/sequential updates to settle
            if (out !== expected_out) begin
                $display("Mismatch at time %0t: in=%b, expected out=%b, got out=%b", 
                         $time, in, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking
    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        in = 0;

        // Apply synchronous reset
        @(posedge clk);
        reset = 1;
        in = 0;

        // Check reset state (Reset state is B, out = 1)
        #1;
        if (out !== 1'b1) begin
            $display("Reset check failed: expected out=1, got out=%b", out);
            errors = errors + 1;
        end

        // Deassert reset
        @(posedge clk);
        reset = 0;

        // State B (out=1) --in=0--> State A (out=0)
        in = 0;
        check_output(1'b0);

        // State A (out=0) --in=0--> State B (out=1)
        in = 0;
        check_output(1'b1);

        // State B (out=1) --in=1--> State B (out=1)
        in = 1;
        check_output(1'b1);

        // State B (out=1) --in=0--> State A (out=0)
        in = 0;
        check_output(1'b0);

        // State A (out=0) --in=1--> State A (out=0)
        in = 1;
        check_output(1'b0);

        // State A (out=0) --in=0--> State B (out=1)
        in = 0;
        check_output(1'b1);

        // Test synchronous reset again while running
        @(posedge clk);
        reset = 1;
        in = 1; // Even with in=1, reset should force state B (out=1)
        #1;
        if (out !== 1'b1) begin
            $display("Mid-run reset check failed: expected out=1, got out=%b", out);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule

