        reset = 1;
        in = 0;
        #10;
        if (out !== 1'b1) begin
            $display("Reset Mismatch: expected out=1 in state B, got out=%b", out);
            errors = errors + 1;
        end

        // Deassert reset
        @(negedge clk);
        reset = 0;

