        in = 0;
        @(posedge clk); // state transition edge
        #1;             // wait for combinational propagation/flop update
        if (out !== 1'b0) begin
            errors = errors + 1;
            $display("ERROR: Transition B -> A failed on in=0. Expected out=0, got %b", out);
        end

        // Transition test: A --in=0--> B
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            errors = errors + 1;
            $display("ERROR: Transition A -> B failed on in=0. Expected out=1, got %b", out);
        end

        // Transition test: B --in=1--> B
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            errors = errors + 1;
            $display("ERROR: Transition B -> B failed on in=1. Expected out=1, got %b", out);
