        #1;
        check_out(1'b1, "State B maintained during reset");

        // Release reset after clock edge
        @(negedge clk);
        areset = 0;

        // Test 1: In State B, input 1 -> should stay in State B (out=1)
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1, "B --1--> B");

