        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0, "B --0--> A");

        // Test 3: In State A, input 1 -> should stay in State A (out=0)
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b0, "A --1--> A");

        @(posedge clk);
        #1;
        check_out(1'b0, "A --1--> A (repeat)");

        // Test 4: In State A, input 0 -> should transition to State B (out=1)
        in = 0;
        @(posedge clk);
