module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg [7:0] in;
    wire [7:0] out;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .in(in),
        .out(out)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;
    integer cycle_count = 0;
    initial begin
        // Apply stimulus and verify outputs
        // Test case 1: all zeros
        in = 8'b00000000;
        #10;
        if (out !== 8'b00000000) begin
            $display("MISMATCH: cycle=%0d time=%0t signal=out expected=%h actual=%h", cycle_count, $time, 8'b00000000, out);
            errors = errors + 1;
        end

        // Test case 2: all ones
        in = 8'b11111111;
        #10;
        if (out !== 8'b11111111) begin
            $display("MISMATCH: cycle=%0d time=%0t signal=out expected=%h actual=%h", cycle_count, $time, 8'b11111111, out);
            errors = errors + 1;
        end

        // Test case 3: random input
        in = 8'b10101010;
        #10;
        if (out !== 8'b01010101) begin
            $display("MISMATCH: cycle=%0d time=%0t signal=out expected=%h actual=%h", cycle_count, $time, 8'b01010101, out);
            errors = errors + 1;
        end

        // Test case 4: edge case (all zeros except one bit)
        in = 8'b10000000;
        #10;
        if (out !== 8'b00000001) begin
            $display("MISMATCH: cycle=%0d time=%0t signal=out expected=%h actual=%h", cycle_count, $time, 8'b00000001, out);
            errors = errors + 1;
        end

        // Test case 5: edge case (all ones except one bit)
        in = 8'b01111111;
        #10;
        if (out !== 8'b11000000) begin
            $display("MISMATCH: cycle=%0d time=%0t signal=out expected=%h actual=%h", cycle_count, $time, 8'b11000000, out);
            errors = errors + 1;
        end

        // Check if all tests pass
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule

